package com.feynman.backend;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.ConfigurationPropertiesScan;

/**
 * Entry point for the Feynman learning-platform backend.
 *
 * <p>The backend evaluates a user's notebooks/pages and scores how well the
 * topic appears to be understood, following the Feynman technique (if you can
 * explain it simply, you understand it). Scores replace the front-end's
 * hard-coded {@code progress.ts} placeholder values.</p>
 */
@SpringBootApplication
@ConfigurationPropertiesScan
public class FeynmanBackendApplication {

    public static void main(String[] args) {
        SpringApplication.run(FeynmanBackendApplication.class, args);
    }
}

package com.feynman.backend.config;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.web.client.RestClient;

import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManagerFactory;
import java.net.http.HttpClient;
import java.security.KeyStore;

/**
 * Builds the {@link RestClient} used to talk to the OpenAI chat completions
 * API. Kept in its own config so it can be mocked in tests.
 *
 * <p>On corporate networks an intercepting proxy often re-signs TLS with a
 * private root CA that the JDK's own {@code cacerts} does not trust (causing
 * "PKIX path building failed"). Windows already trusts that CA, so we point the
 * HTTP client at the {@code Windows-ROOT} certificate store. This is enabled
 * automatically on Windows and can be overridden via
 * {@code openai.trust-store-type} (empty = JDK default).</p>
 */
@Configuration
public class OpenAiClientConfig {

    private static final Logger log = LoggerFactory.getLogger(OpenAiClientConfig.class);

    @Bean
    public RestClient openAiRestClient(
            OpenAiProperties properties,
            @Value("${openai.trust-store-type:}") String trustStoreType) {

        RestClient.Builder builder = RestClient.builder()
                .baseUrl(properties.baseUrl());
        if (properties.apiKey() != null && !properties.apiKey().isBlank()) {
            builder.defaultHeader("Authorization", "Bearer " + properties.apiKey());
        }

        // Resolve which OS truststore to use. Default to Windows-ROOT on Windows
        // so corporate TLS interception certificates are trusted transparently.
        String type = trustStoreType;
        if ((type == null || type.isBlank())
                && System.getProperty("os.name", "").toLowerCase().contains("win")) {
            type = "Windows-ROOT";
        }

        if (type != null && !type.isBlank()) {
            try {
                KeyStore keyStore = KeyStore.getInstance(type);
                keyStore.load(null, null); // OS-backed store loads itself
                TrustManagerFactory tmf = TrustManagerFactory.getInstance(
                        TrustManagerFactory.getDefaultAlgorithm());
                tmf.init(keyStore);
                SSLContext sslContext = SSLContext.getInstance("TLS");
                sslContext.init(null, tmf.getTrustManagers(), null);

                HttpClient httpClient = HttpClient.newBuilder()
                        .sslContext(sslContext)
                        .build();
                builder.requestFactory(new JdkClientHttpRequestFactory(httpClient));
                log.info("OpenAI HTTP client trusting certificates from '{}' store.", type);
            } catch (Exception e) {
                log.warn("Could not initialise trust store '{}'; falling back to JDK default "
                        + "cacerts. TLS to api.openai.com may fail behind a proxy. Cause: {}",
                        type, e.getMessage());
            }
        }

        return builder.build();
    }
}

package com.feynman.backend.config;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.web.client.RestClient;

import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManagerFactory;
import java.net.http.HttpClient;
import java.security.KeyStore;
import java.time.Duration;

/**
 * Builds the {@link RestClient} used to talk to the OpenAI chat completions
 * API. Kept in its own config so it can be mocked in tests.
 *
 * <p>On corporate networks an intercepting proxy often re-signs TLS with a
 * private root CA that the JDK's own {@code cacerts} does not trust (causing
 * "PKIX path building failed"). Windows already trusts that CA, so we point the
 * HTTP client at the {@code Windows-ROOT} certificate store. This is enabled
 * automatically on Windows and can be overridden via
 * {@code openai.trust-store-type} (empty = JDK default).</p>
 */
@Configuration
public class OpenAiClientConfig {

    private static final Logger log = LoggerFactory.getLogger(OpenAiClientConfig.class);

    private static final Duration CONNECT_TIMEOUT = Duration.ofSeconds(10);
    private static final Duration READ_TIMEOUT = Duration.ofSeconds(60);

    @Bean
    public RestClient openAiRestClient(
            OpenAiProperties properties,
            @Value("${openai.trust-store-type:}") String trustStoreType) {

        RestClient.Builder builder = RestClient.builder()
                .baseUrl(properties.baseUrl());
        if (properties.apiKey() != null && !properties.apiKey().isBlank()) {
            builder.defaultHeader("Authorization", "Bearer " + properties.apiKey());
        }

        // Resolve which OS truststore to use. Default to Windows-ROOT on Windows
        // so corporate TLS interception certificates are trusted transparently.
        String type = trustStoreType;
        if ((type == null || type.isBlank())
                && System.getProperty("os.name", "").toLowerCase().contains("win")) {
            type = "Windows-ROOT";
        }

        SSLContext sslContext = null;
        if (type != null && !type.isBlank()) {
            try {
                KeyStore keyStore = KeyStore.getInstance(type);
                keyStore.load(null, null); // OS-backed store loads itself
                TrustManagerFactory tmf = TrustManagerFactory.getInstance(
                        TrustManagerFactory.getDefaultAlgorithm());
                tmf.init(keyStore);
                sslContext = SSLContext.getInstance("TLS");
                sslContext.init(null, tmf.getTrustManagers(), null);
                log.info("OpenAI HTTP client trusting certificates from '{}' store.", type);
            } catch (Exception e) {
                log.warn("Could not initialise trust store '{}'; falling back to JDK default "
                        + "cacerts. TLS to api.openai.com may fail behind a proxy. Cause: {}",
                        type, e.getMessage());
            }
        }

        // Explicit timeouts: without them a stalled OpenAI call blocks the request thread
        // indefinitely, which surfaces to the user as a request that "never returns".
        HttpClient.Builder httpClientBuilder = HttpClient.newBuilder()
                .connectTimeout(CONNECT_TIMEOUT);
        if (sslContext != null) {
            httpClientBuilder.sslContext(sslContext);
        }
        JdkClientHttpRequestFactory requestFactory =
                new JdkClientHttpRequestFactory(httpClientBuilder.build());
        requestFactory.setReadTimeout(READ_TIMEOUT);
        builder.requestFactory(requestFactory);

        return builder.build();
    }
}

package com.feynman.backend.controller;

import com.feynman.backend.dto.VoiceChatResponse;
import com.feynman.backend.service.VoiceChatService;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RequestPart;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;

@RestController
@RequestMapping("/api/voice")
public class VoiceChatController {

    private final VoiceChatService voiceChatService;

    public VoiceChatController(VoiceChatService voiceChatService) {
        this.voiceChatService = voiceChatService;
    }

    /**
     * {@code noteText} is bound with {@link RequestParam} on purpose: browsers send plain
     * {@code FormData} fields without a {@code Content-Type}, which Spring treats as
     * {@code application/octet-stream} and cannot convert to a String via {@code @RequestPart}.
     */
    @PostMapping(value = "/chat", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public VoiceChatResponse chat(
            @RequestPart("audio") MultipartFile audio,
            @RequestParam(value = "noteText", required = false, defaultValue = "") String noteText)
            throws IOException {
        if (audio.isEmpty()) {
            throw new IllegalArgumentException("No audio was received. Please record again.");
        }
        return voiceChatService.chat(audio.getBytes(), audio.getContentType(), noteText);
    }
}

package com.feynman.backend.controller;

import com.feynman.backend.dto.VoiceChatResponse;
import com.feynman.backend.service.VoiceChatService;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RequestPart;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;

@RestController
@RequestMapping("/api/voice")
public class VoiceChatController {

    private final VoiceChatService voiceChatService;

    public VoiceChatController(VoiceChatService voiceChatService) {
        this.voiceChatService = voiceChatService;
    }

    /**
     * {@code noteText} and {@code history} are bound with {@link RequestParam} on purpose:
     * browsers send plain {@code FormData} fields without a {@code Content-Type}, which Spring
     * treats as {@code application/octet-stream} and cannot convert to a String via
     * {@code @RequestPart}.
     *
     * @param history optional JSON array of prior turns ({@code [{"role":"user","text":"..."}]})
     *                so the tutor can follow up instead of restarting the conversation.
     */
    @PostMapping(value = "/chat", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public VoiceChatResponse chat(
            @RequestPart("audio") MultipartFile audio,
            @RequestParam(value = "noteText", required = false, defaultValue = "") String noteText,
            @RequestParam(value = "history", required = false) String history)
            throws IOException {
        if (audio.isEmpty()) {
            throw new IllegalArgumentException("No audio was received. Please record again.");
        }
        return voiceChatService.chat(audio.getBytes(), audio.getContentType(), noteText, history);
    }
}

package com.feynman.backend.dto;

import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * Request payload for {@code POST /api/evaluate}.
 *
 * <p>The frontend sends its full set of notebooks and pages; the backend
 * returns an understanding score (0–100) for every page and an aggregate
 * score for every notebook. When {@code notebookId} is provided, only that
 * notebook (and its pages) is evaluated.</p>
 *
 * @param notebookId Optional filter — evaluate only this notebook when set.
 */
public record EvaluateRequest(
        @NotNull List<NotebookDto> notebooks,
        @NotNull List<PageDto> pages,
        String notebookId
) {
}

package com.feynman.backend.dto;

import java.util.Map;

/**
 * Response payload for {@code POST /api/evaluate}.
 *
 * <p>Scores are split so the frontend can merge page- and notebook-level
 * results independently, matching the shape consumed by {@code setLiveScores}.
 * Each map is keyed by the entity id (matching the frontend seed ids).</p>
 */
public record EvaluationResponse(
        Map<String, ScoreDto> pageScores,
        Map<String, ScoreDto> notebookScores
) {
}

package com.feynman.backend.dto;

/**
 * Mirrors the frontend {@code Notebook} type.
 */
public record NotebookDto(
        String id,
        String title,
        String color
) {
}

package com.feynman.backend.dto;

import java.util.List;

/**
 * Mirrors the frontend {@code Page} type. Represents a single page whose
 * understanding we want to score.
 */
public record PageDto(
        String id,
        String notebookId,
        String parentId,
        String title,
        String content,
        List<TextBoxDto> boxes,
        Integer order
) {
    /** Combined free text of the page (content + all text boxes). */
    public String combinedText() {
        StringBuilder sb = new StringBuilder();
        if (content != null) {
            sb.append(content);
        }
        if (boxes != null) {
            for (TextBoxDto box : boxes) {
                if (box != null && box.text() != null && !box.text().isBlank()) {
                    sb.append("\n").append(box.text());
                }
            }
        }
        return sb.toString().trim();
    }
}

package com.feynman.backend.dto;

/**
 * A single understanding score for a notebook or page.
 *
 * @param score              Understanding percentage, 0–100.
 * @param understandingNotes Short one-line explanation of the score (badge tooltip).
 * @param feedback           Longer, actionable Feynman-style feedback paragraph
 *                           shown inside the evaluated notebook. May be empty.
 */
public record ScoreDto(
        int score,
        String understandingNotes,
        String feedback
) {
}

package com.feynman.backend.dto;

/**
 * Mirrors the frontend {@code TextBox} type: a free-floating text box on the
 * page canvas. Only {@code text} matters for evaluation.
 */
public record TextBoxDto(
        String id,
        Double x,
        Double y,
        String text,
        Double width
) {
}

package com.feynman.backend.service;

import com.feynman.backend.config.OpenAiProperties;
import com.feynman.backend.dto.EvaluateRequest;
import com.feynman.backend.dto.EvaluationResponse;
import com.feynman.backend.dto.NotebookDto;
import com.feynman.backend.dto.PageDto;
import com.feynman.backend.dto.ScoreDto;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientResponseException;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Evaluates a user's notebooks/pages and scores how well each topic seems to
 * be understood, following the Feynman technique: clear, simple, structured
 * explanations score higher; sparse notes or unexplained jargon score lower.
 *
 * <p>When {@code openai.mock=true}, a deterministic heuristic is used so the
 * app runs fully offline. With mock scoring disabled, a missing key or failed
 * OpenAI request is reported instead of silently returning a mock score.</p>
 */
@Service
public class OpenAiEvaluationService {

    private static final Logger log = LoggerFactory.getLogger(OpenAiEvaluationService.class);

    private final RestClient openAiRestClient;
    private final OpenAiProperties properties;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public OpenAiEvaluationService(RestClient openAiRestClient, OpenAiProperties properties) {
        this.openAiRestClient = openAiRestClient;
        this.properties = properties;
        // Startup diagnostic: confirms what Spring actually bound WITHOUT leaking
        // the secret. If keyPresent=false here, the env var never reached this
        // JVM process (wrong run config, not restarted, or set in another shell).
        String key = properties.apiKey();
        String masked = (key == null || key.isBlank())
                ? "<none>"
                : "set (len=" + key.trim().length() + ", ..." 
                    + key.substring(Math.max(0, key.length() - 4)) + ")";
        log.debug("OpenAI config → mock={}, keyPresent={}, key={}, model={}",
                properties.mock(), properties.hasApiKey(), masked, properties.model());
    }

    /**
     * Score every page, then aggregate page scores into a notebook score.
     * When {@code request.notebookId()} is set, only that notebook and its
     * pages are evaluated.
     */
    public EvaluationResponse evaluate(EvaluateRequest request) {
        String filterId = request.notebookId();

        List<NotebookDto> notebooks = (request.notebooks() == null ? List.<NotebookDto>of() : request.notebooks())
                .stream()
                .filter(nb -> filterId == null || filterId.equals(nb.id()))
                .toList();

        List<PageDto> pages = (request.pages() == null ? List.<PageDto>of() : request.pages())
                .stream()
                .filter(p -> filterId == null || filterId.equals(p.notebookId()))
                .toList();

        if (!properties.useMock() && !properties.hasApiKey() && !pages.isEmpty()) {
            throw new EvaluationException(
                    "OPENAI_API_KEY is missing. Set it or enable openai.mock=true for offline scoring.");
        }

        Map<String, ScoreDto> pageScores = new LinkedHashMap<>();

        // --- Per-page scoring ---------------------------------------------------
        Map<String, Integer> pageScoresById = new LinkedHashMap<>();
        for (PageDto page : pages) {
            ScoreDto score = properties.useMock() ? mockScore(page) : llmScore(page);
            pageScores.put(page.id(), score);
            pageScoresById.put(page.id(), score.score());
        }

        // --- Notebook aggregation (average of its pages) ------------------------
        Map<String, ScoreDto> notebookScores = new LinkedHashMap<>();
        for (NotebookDto notebook : notebooks) {
            List<Integer> scores = new ArrayList<>();
            for (PageDto page : pages) {
                if (notebook.id().equals(page.notebookId())) {
                    scores.add(pageScoresById.getOrDefault(page.id(), 0));
                }
            }
            int avg = scores.isEmpty()
                    ? 0
                    : (int) Math.round(scores.stream().mapToInt(Integer::intValue).average().orElse(0));
            String notes = scores.isEmpty()
                    ? "No pages to evaluate yet."
                    : "Average understanding across " + scores.size() + " page(s).";
            String notebookFeedback = scores.isEmpty()
                    ? "Add and evaluate some pages to get feedback for this notebook."
                    : "Overall this notebook averages " + avg + "% understanding across "
                        + scores.size() + " page(s). Open individual pages to see targeted feedback "
                        + "on what to explain more simply or in more depth.";
            notebookScores.put(notebook.id(), new ScoreDto(avg, notes, notebookFeedback, List.of()));
        }

        return new EvaluationResponse(pageScores, notebookScores);
    }

    // ---------------------------------------------------------------------------
    // Model discovery
    // ---------------------------------------------------------------------------

    /**
     * List the model IDs the configured API key is allowed to use by calling
     * {@code GET /v1/models}. Useful to discover which models can replace the
     * default {@code openai.model}.
     *
     * @return sorted, distinct list of model IDs returned by the provider.
     */
    public List<String> listModels() {
        try {
            String responseJson = openAiRestClient.get()
                    .uri("/models")
                    .accept(MediaType.APPLICATION_JSON)
                    .retrieve()
                    .body(String.class);

            JsonNode data = objectMapper.readTree(responseJson).path("data");
            List<String> models = new ArrayList<>();
            for (JsonNode node : data) {
                String id = node.path("id").asText("");
                if (!id.isBlank()) {
                    models.add(id);
                }
            }
            models.sort(String::compareTo);
            return models;
        } catch (RestClientResponseException e) {
            String detail = openAiErrorDetail(
                    e.getStatusCode().value(), e.getResponseBodyAsString(), properties.model());
            log.error("Listing models failed — {} Body: {}", detail, e.getResponseBodyAsString());
            throw new EvaluationException(detail, e);
        } catch (Exception e) {
            log.error("Listing models failed. Cause: {}", e.getMessage());
            throw new EvaluationException(
                    "Could not list OpenAI models. Check OPENAI_API_KEY, base URL, and network configuration.", e);
        }
    }

    // ---------------------------------------------------------------------------
    // OpenAI-backed scoring
    // ---------------------------------------------------------------------------

    private ScoreDto llmScore(PageDto page) {
        String text = page.combinedText();
        if (text.isBlank()) {
            return new ScoreDto(0, "Page is empty.",
                    "There are no notes on this page yet to give feedback on.", List.of());
        }

        String systemPrompt = """
                You are an expert tutor grading a learner's notes using the Feynman technique:
                if someone can explain a topic simply, clearly and completely, they understand it well.
                Grade how well the learner appears to UNDERSTAND the topic based only on their notes.
                Reward: clear plain-language explanations, correct structure, worked examples,
                cause/effect reasoning, and coverage. Penalise: sparse notes, unexplained jargon,
                copy-paste lists without explanation, and contradictions.
                Respond ONLY with strict JSON of the form:
                {"score": <integer 0-100>, "understandingNotes": "<one short sentence>", \
                "feedback": "<2-4 sentences of specific, encouraging, actionable feedback: \
                what is explained well and what to clarify or expand to understand it better>", \
                "todos": ["<short imperative action the learner should do next, max ~12 words>", \
                "<another action>"]}
                Provide 2-5 todos. Each todo must be a concrete, self-contained action \
                (e.g. "Add a worked example for Bayes' theorem"). Return an empty array if \
                the notes are already excellent.""";

        String userPrompt = "Title: " + safe(page.title()) + "\n\nNotes:\n" + text;

        try {
            Map<String, Object> body = new LinkedHashMap<>();
            body.put("model", properties.model());
            // Newer models (gpt-5.x family and the o-series reasoning models) only
            // accept the default temperature and reject an explicit value with a
            // 400. Send temperature=0 for determinism only where it's supported.
            if (supportsCustomTemperature(properties.model())) {
                body.put("temperature", 0);
            }
            body.put("response_format", Map.of("type", "json_object"));
            body.put("messages", List.of(
                    Map.of("role", "system", "content", systemPrompt),
                    Map.of("role", "user", "content", userPrompt)
            ));

            String responseJson = openAiRestClient.post()
                    .uri("/chat/completions")
                    .contentType(MediaType.APPLICATION_JSON)
                    .body(body)
                    .retrieve()
                    .body(String.class);

            JsonNode root = objectMapper.readTree(responseJson);
            String content = root.path("choices").path(0).path("message").path("content").asText();
            JsonNode parsed = objectMapper.readTree(content);

            int score = clamp(parsed.path("score").asInt(0));
            String notes = parsed.path("understandingNotes").asText("");
            String feedback = parsed.path("feedback").asText("");
            List<String> todos = new ArrayList<>();
            for (JsonNode item : parsed.path("todos")) {
                String todo = item.asText("").trim();
                if (!todo.isBlank()) {
                    todos.add(todo);
                }
            }
            return new ScoreDto(score, notes, feedback, todos);
        } catch (RestClientResponseException e) {
            // OpenAI returned an HTTP error — translate common cases into clear,
            // actionable messages instead of a generic failure.
            String detail = openAiErrorDetail(
                    e.getStatusCode().value(), e.getResponseBodyAsString(), properties.model());
            log.error("LLM scoring failed for page {} — {} Body: {}",
                    page.id(), detail, e.getResponseBodyAsString());
            throw new EvaluationException(detail, e);
        } catch (Exception e) {
            log.error("LLM scoring failed for page {}. Cause: {}", page.id(), e.getMessage());
            throw new EvaluationException(
                    "OpenAI evaluation failed. Check OPENAI_API_KEY, model, and network configuration.", e);
        }
    }

    /**
     * Map an OpenAI HTTP error status (and body) into a clear, actionable
     * message. Package-private and static so it can be unit-tested directly.
     */
    static String openAiErrorDetail(int status, String responseBody, String model) {
        String body = responseBody == null ? "" : responseBody;
        return switch (status) {
            case 401 -> "OpenAI rejected the API key (401). Check OPENAI_API_KEY is valid and not revoked.";
            case 403 -> "OpenAI denied access (403). The key may lack permission for model '"
                    + model + "'.";
            case 404 -> "OpenAI model '" + model
                    + "' not found (404). Set OPENAI_MODEL to a model your account can use.";
            case 429 -> body.contains("insufficient_quota")
                    ? "OpenAI account has no credits. Add billing credits at "
                        + "platform.openai.com/settings/organization/billing."
                    : "OpenAI rate limit hit (429). Wait a moment and try again.";
            default -> "OpenAI request failed (HTTP " + status + ").";
        };
    }

    // ---------------------------------------------------------------------------
    // Deterministic offline heuristic
    // ---------------------------------------------------------------------------

    /**
     * Deterministic offline score used when mock scoring is enabled.
     * Length alone is not understanding, so uncertainty and missing
     * explanations lower the result.
     */
    ScoreDto mockScore(PageDto page) {
        String text = page.combinedText();
        if (text.isBlank()) {
            return new ScoreDto(0, "Page is empty.",
                    "There are no notes on this page yet to give feedback on.", List.of());
        }

        String normalized = text.toLowerCase(Locale.ROOT);
        int words = text.split("\\s+").length;
        // Notes receive limited credit for effort, but not mastery from length.
        int effort = Math.min(70, words * 70 / 120);

        int evidence = 0;
        if (normalized.contains("because") || normalized.contains("therefore")
                || normalized.contains("which means") || normalized.contains("as a result")) {
            evidence += 10;
        }
        if (normalized.contains("for example") || normalized.contains("example:")) {
            evidence += 8;
        }
        if (normalized.contains("why") || normalized.contains("how")) {
            evidence += 5;
        }
        if (normalized.contains("=")) {
            evidence += 3;
        }

        int uncertainty = countOccurrences(normalized,
                "not sure", "no idea", "fuzzy", "unclear", "maybe", "i think",
                "unsure", "wrong answer", "need to review", "not totally clear");
        int penalty = Math.min(30, uncertainty * 3);
        // Strong admissions of missing understanding should weigh more than
        // ordinary hedging, without penalising merely incomplete notes equally.
        int severeUncertainty = countOccurrences(normalized,
                "no idea", "never understood", "completely confused", "don't understand");
        int severePenalty = Math.min(20, severeUncertainty * 9);
        int score = clamp(effort + evidence - penalty - severePenalty);
        return new ScoreDto(score,
                "Heuristic score from " + words
                        + " word(s), with explanation evidence and uncertainty markers considered (offline mock).",
                mockFeedback(score, words, evidence, penalty + severePenalty),
                mockTodos(words, evidence, penalty + severePenalty));
    }

    /**
     * Deterministic offline to-do items that mirror what the heuristic flagged,
     * so mock mode can populate tick-box to-dos without an API call.
     */
    private static List<String> mockTodos(int words, int evidence, int uncertaintyPenalty) {
        List<String> todos = new ArrayList<>();
        if (evidence == 0) {
            todos.add("Explain WHY the key idea is true (use \"because\"/\"therefore\").");
            todos.add("Add a concrete worked example.");
        }
        if (uncertaintyPenalty > 0) {
            todos.add("Rewrite uncertain phrases as confident explanations.");
        }
        if (words < 40) {
            todos.add("Expand the notes with more detail and coverage.");
        }
        if (todos.isEmpty()) {
            todos.add("Teach the topic aloud from memory to confirm understanding.");
        }
        return todos;
    }

    /**
     * Deterministic offline feedback that mirrors what the heuristic rewarded or
     * penalised, so mock mode still shows useful, distinguishable guidance.
     */
    private static String mockFeedback(int score, int words, int evidence, int uncertaintyPenalty) {
        StringBuilder sb = new StringBuilder();
        if (score >= 75) {
            sb.append("Strong understanding: your notes explain the topic clearly and in your own words. ");
        } else if (score >= 33) {
            sb.append("Developing understanding: the core idea is there but parts could be explained more simply. ");
        } else {
            sb.append("Early understanding: the notes are sparse or uncertain, so keep building them up. ");
        }
        if (evidence > 0) {
            sb.append("Good use of reasoning and examples (\"because\", \"for example\", etc.). ");
        } else {
            sb.append("Try adding cause/effect reasoning (\"because\", \"therefore\") and a worked example. ");
        }
        if (uncertaintyPenalty > 0) {
            sb.append("Some phrases signal uncertainty — revisit those and rewrite them as confident explanations. ");
        }
        if (words < 40) {
            sb.append("Expanding the notes with more detail would demonstrate deeper understanding.");
        }
        return sb.toString().trim() + " (offline mock feedback)";
    }

    private static int countOccurrences(String text, String... terms) {
        int count = 0;
        for (String term : terms) {
            int from = 0;
            while ((from = text.indexOf(term, from)) >= 0) {
                count++;
                from += term.length();
            }
        }
        return count;
    }

    private static int clamp(int v) {
        return Math.max(0, Math.min(100, v));
    }

    /**
     * Whether a model accepts an explicit {@code temperature} value. The
     * gpt-5.x family and the o-series reasoning models (o1/o3/o4) only support
     * the default temperature and return HTTP 400 for any explicit value.
     */
    static boolean supportsCustomTemperature(String model) {
        if (model == null) {
            return true;
        }
        String m = model.toLowerCase(Locale.ROOT);
        boolean fixedTemperature = m.startsWith("gpt-5")
                || m.startsWith("o1")
                || m.startsWith("o3")
                || m.startsWith("o4");
        return !fixedTemperature;
    }

    private static String safe(String s) {
        return s == null ? "" : s;
    }

    /**
     * Thrown when evaluation cannot be completed.
     */
    public static class EvaluationException extends RuntimeException {
        public EvaluationException(String message) {
            super(message);
        }

        public EvaluationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}

package com.feynman.backend.service;

import com.feynman.backend.config.OpenAiProperties;
import com.feynman.backend.dto.EvaluateRequest;
import com.feynman.backend.dto.EvaluationResponse;
import com.feynman.backend.dto.NotebookDto;
import com.feynman.backend.dto.PageDto;
import com.feynman.backend.dto.ScoreDto;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientResponseException;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Evaluates a user's notebooks/pages and scores how well each topic seems to
 * be understood, following the Feynman technique: clear, simple, structured
 * explanations score higher; sparse notes or unexplained jargon score lower.
 *
 * <p>When {@code openai.mock=true}, a deterministic heuristic is used so the
 * app runs fully offline. With mock scoring disabled, a missing key or failed
 * OpenAI request is reported instead of silently returning a mock score.</p>
 */
@Service
public class OpenAiEvaluationService {

    private static final Logger log = LoggerFactory.getLogger(OpenAiEvaluationService.class);

    private final RestClient openAiRestClient;
    private final OpenAiProperties properties;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public OpenAiEvaluationService(RestClient openAiRestClient, OpenAiProperties properties) {
        this.openAiRestClient = openAiRestClient;
        this.properties = properties;
        // Startup diagnostic: confirms what Spring actually bound WITHOUT leaking
        // the secret. If keyPresent=false here, the env var never reached this
        // JVM process (wrong run config, not restarted, or set in another shell).
        String key = properties.apiKey();
        String masked = (key == null || key.isBlank())
                ? "<none>"
                : "set (len=" + key.trim().length() + ", ..." 
                    + key.substring(Math.max(0, key.length() - 4)) + ")";
        log.debug("OpenAI config → mock={}, keyPresent={}, key={}, model={}",
                properties.mock(), properties.hasApiKey(), masked, properties.model());
    }

    /**
     * Score every page, then aggregate page scores into a notebook score.
     * When {@code request.notebookId()} is set, only that notebook and its
     * pages are evaluated. When {@code request.pageId()} is set, only that
     * single page is scored and notebook aggregation is skipped — this keeps
     * the request cheap for notebooks with many pages/subpages.
     */
    public EvaluationResponse evaluate(EvaluateRequest request) {
        String filterId = request.notebookId();
        String pageId = request.pageId();
        boolean singlePage = pageId != null && !pageId.isBlank();

        // A single-page request scores only that page; a notebook request scores
        // every page in the notebook; otherwise the whole dataset is scored.
        List<PageDto> pages = (request.pages() == null ? List.<PageDto>of() : request.pages())
                .stream()
                .filter(p -> singlePage
                        ? pageId.equals(p.id())
                        : (filterId == null || filterId.equals(p.notebookId())))
                .toList();

        // Notebook aggregation is meaningless for a single page, so skip it: a
        // one-page average would otherwise clobber the notebook's real score.
        List<NotebookDto> notebooks = singlePage
                ? List.of()
                : (request.notebooks() == null ? List.<NotebookDto>of() : request.notebooks())
                        .stream()
                        .filter(nb -> filterId == null || filterId.equals(nb.id()))
                        .toList();

        if (!properties.useMock() && !properties.hasApiKey() && !pages.isEmpty()) {
            throw new EvaluationException(
                    "OPENAI_API_KEY is missing. Set it or enable openai.mock=true for offline scoring.");
        }

        Map<String, ScoreDto> pageScores = new LinkedHashMap<>();

        // --- Per-page scoring ---------------------------------------------------
        Map<String, Integer> pageScoresById = new LinkedHashMap<>();
        for (PageDto page : pages) {
            ScoreDto score = properties.useMock() ? mockScore(page) : llmScore(page);
            pageScores.put(page.id(), score);
            pageScoresById.put(page.id(), score.score());
        }

        // --- Notebook aggregation (average of its pages) ------------------------
        Map<String, ScoreDto> notebookScores = new LinkedHashMap<>();
        for (NotebookDto notebook : notebooks) {
            List<Integer> scores = new ArrayList<>();
            for (PageDto page : pages) {
                if (notebook.id().equals(page.notebookId())) {
                    scores.add(pageScoresById.getOrDefault(page.id(), 0));
                }
            }
            int avg = scores.isEmpty()
                    ? 0
                    : (int) Math.round(scores.stream().mapToInt(Integer::intValue).average().orElse(0));
            String notes = scores.isEmpty()
                    ? "No pages to evaluate yet."
                    : "Average understanding across " + scores.size() + " page(s).";
            String notebookFeedback = scores.isEmpty()
                    ? "Add and evaluate some pages to get feedback for this notebook."
                    : "Overall this notebook averages " + avg + "% understanding across "
                        + scores.size() + " page(s). Open individual pages to see targeted feedback "
                        + "on what to explain more simply or in more depth.";
            notebookScores.put(notebook.id(), new ScoreDto(avg, notes, notebookFeedback, List.of()));
        }

        return new EvaluationResponse(pageScores, notebookScores);
    }

    // ---------------------------------------------------------------------------
    // Model discovery
    // ---------------------------------------------------------------------------

    /**
     * List the model IDs the configured API key is allowed to use by calling
     * {@code GET /v1/models}. Useful to discover which models can replace the
     * default {@code openai.model}.
     *
     * @return sorted, distinct list of model IDs returned by the provider.
     */
    public List<String> listModels() {
        try {
            String responseJson = openAiRestClient.get()
                    .uri("/models")
                    .accept(MediaType.APPLICATION_JSON)
                    .retrieve()
                    .body(String.class);

            JsonNode data = objectMapper.readTree(responseJson).path("data");
            List<String> models = new ArrayList<>();
            for (JsonNode node : data) {
                String id = node.path("id").asText("");
                if (!id.isBlank()) {
                    models.add(id);
                }
            }
            models.sort(String::compareTo);
            return models;
        } catch (RestClientResponseException e) {
            String detail = openAiErrorDetail(
                    e.getStatusCode().value(), e.getResponseBodyAsString(), properties.model());
            log.error("Listing models failed — {} Body: {}", detail, e.getResponseBodyAsString());
            throw new EvaluationException(detail, e);
        } catch (Exception e) {
            log.error("Listing models failed. Cause: {}", e.getMessage());
            throw new EvaluationException(
                    "Could not list OpenAI models. Check OPENAI_API_KEY, base URL, and network configuration.", e);
        }
    }

    // ---------------------------------------------------------------------------
    // OpenAI-backed scoring
    // ---------------------------------------------------------------------------

    private ScoreDto llmScore(PageDto page) {
        String text = page.combinedText();
        if (text.isBlank()) {
            return new ScoreDto(0, "Page is empty.",
                    "There are no notes on this page yet to give feedback on.", List.of());
        }

        String systemPrompt = """
                You are an expert tutor grading a learner's notes using the Feynman technique:
                if someone can explain a topic simply, clearly and completely, they understand it well.
                Grade how well the learner appears to UNDERSTAND the topic based only on their notes.
                Reward: clear plain-language explanations, correct structure, worked examples,
                cause/effect reasoning, and coverage. Penalise: sparse notes, unexplained jargon,
                copy-paste lists without explanation, and contradictions.
                Respond ONLY with strict JSON of the form:
                {"score": <integer 0-100>, "understandingNotes": "<one short sentence>", \
                "feedback": "<2-4 sentences of specific, encouraging, actionable feedback: \
                what is explained well and what to clarify or expand to understand it better>", \
                "todos": ["<short imperative action the learner should do next, max ~12 words>", \
                "<another action>"]}
                Provide 2-5 todos. Each todo must be a concrete, self-contained action \
                (e.g. "Add a worked example for Bayes' theorem"). Return an empty array if \
                the notes are already excellent.""";

        String userPrompt = "Title: " + safe(page.title()) + "\n\nNotes:\n" + text;

        try {
            Map<String, Object> body = new LinkedHashMap<>();
            body.put("model", properties.model());
            // Newer models (gpt-5.x family and the o-series reasoning models) only
            // accept the default temperature and reject an explicit value with a
            // 400. Send temperature=0 for determinism only where it's supported.
            if (supportsCustomTemperature(properties.model())) {
                body.put("temperature", 0);
            }
            body.put("response_format", Map.of("type", "json_object"));
            body.put("messages", List.of(
                    Map.of("role", "system", "content", systemPrompt),
                    Map.of("role", "user", "content", userPrompt)
            ));

            String responseJson = openAiRestClient.post()
                    .uri("/chat/completions")
                    .contentType(MediaType.APPLICATION_JSON)
                    .body(body)
                    .retrieve()
                    .body(String.class);

            JsonNode root = objectMapper.readTree(responseJson);
            String content = root.path("choices").path(0).path("message").path("content").asText();
            JsonNode parsed = objectMapper.readTree(content);

            int score = clamp(parsed.path("score").asInt(0));
            String notes = parsed.path("understandingNotes").asText("");
            String feedback = parsed.path("feedback").asText("");
            List<String> todos = new ArrayList<>();
            for (JsonNode item : parsed.path("todos")) {
                String todo = item.asText("").trim();
                if (!todo.isBlank()) {
                    todos.add(todo);
                }
            }
            return new ScoreDto(score, notes, feedback, todos);
        } catch (RestClientResponseException e) {
            // OpenAI returned an HTTP error — translate common cases into clear,
            // actionable messages instead of a generic failure.
            String detail = openAiErrorDetail(
                    e.getStatusCode().value(), e.getResponseBodyAsString(), properties.model());
            log.error("LLM scoring failed for page {} — {} Body: {}",
                    page.id(), detail, e.getResponseBodyAsString());
            throw new EvaluationException(detail, e);
        } catch (Exception e) {
            log.error("LLM scoring failed for page {}. Cause: {}", page.id(), e.getMessage());
            throw new EvaluationException(
                    "OpenAI evaluation failed. Check OPENAI_API_KEY, model, and network configuration.", e);
        }
    }

    /**
     * Map an OpenAI HTTP error status (and body) into a clear, actionable
     * message. Package-private and static so it can be unit-tested directly.
     */
    static String openAiErrorDetail(int status, String responseBody, String model) {
        String body = responseBody == null ? "" : responseBody;
        return switch (status) {
            case 401 -> "OpenAI rejected the API key (401). Check OPENAI_API_KEY is valid and not revoked.";
            case 403 -> "OpenAI denied access (403). The key may lack permission for model '"
                    + model + "'.";
            case 404 -> "OpenAI model '" + model
                    + "' not found (404). Set OPENAI_MODEL to a model your account can use.";
            case 429 -> body.contains("insufficient_quota")
                    ? "OpenAI account has no credits. Add billing credits at "
                        + "platform.openai.com/settings/organization/billing."
                    : "OpenAI rate limit hit (429). Wait a moment and try again.";
            default -> "OpenAI request failed (HTTP " + status + ").";
        };
    }

    // ---------------------------------------------------------------------------
    // Deterministic offline heuristic
    // ---------------------------------------------------------------------------

    /**
     * Deterministic offline score used when mock scoring is enabled.
     * Length alone is not understanding, so uncertainty and missing
     * explanations lower the result.
     */
    ScoreDto mockScore(PageDto page) {
        String text = page.combinedText();
        if (text.isBlank()) {
            return new ScoreDto(0, "Page is empty.",
                    "There are no notes on this page yet to give feedback on.", List.of());
        }

        String normalized = text.toLowerCase(Locale.ROOT);
        int words = text.split("\\s+").length;
        // Notes receive limited credit for effort, but not mastery from length.
        int effort = Math.min(70, words * 70 / 120);

        int evidence = 0;
        if (normalized.contains("because") || normalized.contains("therefore")
                || normalized.contains("which means") || normalized.contains("as a result")) {
            evidence += 10;
        }
        if (normalized.contains("for example") || normalized.contains("example:")) {
            evidence += 8;
        }
        if (normalized.contains("why") || normalized.contains("how")) {
            evidence += 5;
        }
        if (normalized.contains("=")) {
            evidence += 3;
        }

        int uncertainty = countOccurrences(normalized,
                "not sure", "no idea", "fuzzy", "unclear", "maybe", "i think",
                "unsure", "wrong answer", "need to review", "not totally clear");
        int penalty = Math.min(30, uncertainty * 3);
        // Strong admissions of missing understanding should weigh more than
        // ordinary hedging, without penalising merely incomplete notes equally.
        int severeUncertainty = countOccurrences(normalized,
                "no idea", "never understood", "completely confused", "don't understand");
        int severePenalty = Math.min(20, severeUncertainty * 9);
        int score = clamp(effort + evidence - penalty - severePenalty);
        return new ScoreDto(score,
                "Heuristic score from " + words
                        + " word(s), with explanation evidence and uncertainty markers considered (offline mock).",
                mockFeedback(score, words, evidence, penalty + severePenalty),
                mockTodos(words, evidence, penalty + severePenalty));
    }

    /**
     * Deterministic offline to-do items that mirror what the heuristic flagged,
     * so mock mode can populate tick-box to-dos without an API call.
     */
    private static List<String> mockTodos(int words, int evidence, int uncertaintyPenalty) {
        List<String> todos = new ArrayList<>();
        if (evidence == 0) {
            todos.add("Explain WHY the key idea is true (use \"because\"/\"therefore\").");
            todos.add("Add a concrete worked example.");
        }
        if (uncertaintyPenalty > 0) {
            todos.add("Rewrite uncertain phrases as confident explanations.");
        }
        if (words < 40) {
            todos.add("Expand the notes with more detail and coverage.");
        }
        if (todos.isEmpty()) {
            todos.add("Teach the topic aloud from memory to confirm understanding.");
        }
        return todos;
    }

    /**
     * Deterministic offline feedback that mirrors what the heuristic rewarded or
     * penalised, so mock mode still shows useful, distinguishable guidance.
     */
    private static String mockFeedback(int score, int words, int evidence, int uncertaintyPenalty) {
        StringBuilder sb = new StringBuilder();
        if (score >= 75) {
            sb.append("Strong understanding: your notes explain the topic clearly and in your own words. ");
        } else if (score >= 33) {
            sb.append("Developing understanding: the core idea is there but parts could be explained more simply. ");
        } else {
            sb.append("Early understanding: the notes are sparse or uncertain, so keep building them up. ");
        }
        if (evidence > 0) {
            sb.append("Good use of reasoning and examples (\"because\", \"for example\", etc.). ");
        } else {
            sb.append("Try adding cause/effect reasoning (\"because\", \"therefore\") and a worked example. ");
        }
        if (uncertaintyPenalty > 0) {
            sb.append("Some phrases signal uncertainty — revisit those and rewrite them as confident explanations. ");
        }
        if (words < 40) {
            sb.append("Expanding the notes with more detail would demonstrate deeper understanding.");
        }
        return sb.toString().trim() + " (offline mock feedback)";
    }

    private static int countOccurrences(String text, String... terms) {
        int count = 0;
        for (String term : terms) {
            int from = 0;
            while ((from = text.indexOf(term, from)) >= 0) {
                count++;
                from += term.length();
            }
        }
        return count;
    }

    private static int clamp(int v) {
        return Math.max(0, Math.min(100, v));
    }

    /**
     * Whether a model accepts an explicit {@code temperature} value. The
     * gpt-5.x family and the o-series reasoning models (o1/o3/o4) only support
     * the default temperature and return HTTP 400 for any explicit value.
     */
    static boolean supportsCustomTemperature(String model) {
        if (model == null) {
            return true;
        }
        String m = model.toLowerCase(Locale.ROOT);
        boolean fixedTemperature = m.startsWith("gpt-5")
                || m.startsWith("o1")
                || m.startsWith("o3")
                || m.startsWith("o4");
        return !fixedTemperature;
    }

    private static String safe(String s) {
        return s == null ? "" : s;
    }

    /**
     * Thrown when evaluation cannot be completed.
     */
    public static class EvaluationException extends RuntimeException {
        public EvaluationException(String message) {
            super(message);
        }

        public EvaluationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}

package com.feynman.backend.service;

import com.feynman.backend.config.OpenAiProperties;
import com.feynman.backend.dto.VoiceChatResponse;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.ByteArrayResource;
import org.springframework.http.MediaType;
import org.springframework.http.client.MultipartBodyBuilder;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientResponseException;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

@Service
public class VoiceChatService {

    private static final Logger log = LoggerFactory.getLogger(VoiceChatService.class);

    private final RestClient openAiRestClient;
    private final OpenAiProperties properties;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public VoiceChatService(RestClient openAiRestClient, OpenAiProperties properties) {
        this.openAiRestClient = openAiRestClient;
        this.properties = properties;
    }

    // gpt-audio only accepts wav and mp3 as input formats
    private static final java.util.Set<String> SUPPORTED_FORMATS = java.util.Set.of("wav", "mp3");

    public VoiceChatResponse chat(byte[] audioBytes, String mimeType, String noteText) {
        String rawFormat = mimeType != null && mimeType.contains("/")
                ? mimeType.substring(mimeType.indexOf('/') + 1).split(";")[0]
                : "wav";
        // m4a arrives as "x-m4a" or "mp4" — treat as mp3-compatible
        String audioFormat = switch (rawFormat) {
            case "mpeg", "x-mpeg", "mp4", "x-m4a", "m4a" -> "mp3";
            default -> rawFormat;
        };

        // gpt-audio rejects ogg/webm outright (browser MediaRecorder output), so transcode via ffmpeg first
        if ("ogg".equals(audioFormat) || "webm".equals(audioFormat)) {
            audioBytes = convertToWav(audioBytes, audioFormat);
            audioFormat = "wav";
        }

        if (!SUPPORTED_FORMATS.contains(audioFormat)) {
            throw new VoiceException(
                    "Unsupported audio format '" + audioFormat + "'. Send wav or mp3.");
        }

        String base64Audio = Base64.getEncoder().encodeToString(audioBytes);

        String systemPrompt = """
                You are a supportive Feynman-technique tutor. The learner will send you a voice \
                explanation of a topic. You have their reference notes below.
                Compare what they said to those notes: praise what they explained correctly, \
                point out any gaps or misconceptions, then ask ONE focused reflection question \
                to deepen their understanding. Keep your response concise and encouraging."""
                + "\n\nReference notes:\n" + noteText;

        Map<String, Object> inputAudio = new LinkedHashMap<>();
        inputAudio.put("type", "input_audio");
        inputAudio.put("input_audio", Map.of("data", base64Audio, "format", audioFormat));

        Map<String, Object> body = new LinkedHashMap<>();
        body.put("model", properties.audioModel());
        body.put("modalities", List.of("text", "audio"));
        body.put("audio", Map.of("voice", "alloy", "format", "wav"));
        body.put("messages", List.of(
                Map.of("role", "system", "content", systemPrompt),
                Map.of("role", "user", "content", List.of(inputAudio))
        ));

        try {
            String responseJson = openAiRestClient.post()
                    .uri("/chat/completions")
                    .contentType(MediaType.APPLICATION_JSON)
                    .body(body)
                    .retrieve()
                    .body(String.class);

            JsonNode audio = objectMapper.readTree(responseJson)
                    .path("choices").path(0).path("message").path("audio");

            String userTranscript = transcribeAudio(audioBytes);
            String transcript = audio.path("transcript").asText("");
            String audioData  = audio.path("data").asText("");
            return new VoiceChatResponse(userTranscript, transcript, audioData);

        } catch (RestClientResponseException e) {
            String detail = OpenAiEvaluationService.openAiErrorDetail(
                    e.getStatusCode().value(), e.getResponseBodyAsString(), properties.audioModel());
            log.error("Voice chat failed — {} Body: {}", detail, e.getResponseBodyAsString());
            throw new VoiceException(detail, e);
        } catch (Exception e) {
            log.error("Voice chat failed. Cause: {}", e.getMessage());
            throw new VoiceException(
                    "Voice chat failed. Check OPENAI_API_KEY, audio-model, and network configuration.", e);
        }
    }

    /** Separately transcribes the learner's own audio via OpenAI's speech-to-text endpoint. */
    private String transcribeAudio(byte[] wavBytes) {
        MultipartBodyBuilder builder = new MultipartBodyBuilder();
        builder.part("file", new ByteArrayResource(wavBytes) {
            @Override
            public String getFilename() {
                return "audio.wav";
            }
        });
        builder.part("model", properties.transcriptionModel());

        String responseJson = openAiRestClient.post()
                .uri("/audio/transcriptions")
                .contentType(MediaType.MULTIPART_FORM_DATA)
                .body(builder.build())
                .retrieve()
                .body(String.class);

        try {
            return objectMapper.readTree(responseJson).path("text").asText("");
        } catch (Exception e) {
            log.warn("Could not parse transcription response: {}", e.getMessage());
            return "";
        }
    }

    /** Shells out to the system {@code ffmpeg} binary to transcode ogg/webm audio to PCM WAV. */
    private byte[] convertToWav(byte[] inputBytes, String sourceFormat) {
        Path inputFile = null;
        Path wavFile = null;
        try {
            inputFile = Files.createTempFile("voice-", "." + sourceFormat);
            wavFile = Files.createTempFile("voice-", ".wav");
            Files.write(inputFile, inputBytes);

            Process process = new ProcessBuilder(
                    "ffmpeg", "-y", "-i", inputFile.toString(),
                    "-ar", "24000", "-ac", "1", wavFile.toString())
                    .redirectErrorStream(true)
                    .start();

            if (!process.waitFor(30, TimeUnit.SECONDS)) {
                process.destroyForcibly();
                throw new VoiceException("Audio conversion timed out.");
            }
            if (process.exitValue() != 0) {
                throw new VoiceException("Audio conversion failed (ffmpeg exit code "
                        + process.exitValue() + ").");
            }
            return Files.readAllBytes(wavFile);
        } catch (IOException e) {
            throw new VoiceException(
                    "Could not convert " + sourceFormat + " audio to wav. Is ffmpeg installed and on PATH?", e);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new VoiceException("Audio conversion was interrupted.", e);
        } finally {
            deleteQuietly(inputFile);
            deleteQuietly(wavFile);
        }
    }

    private void deleteQuietly(Path path) {
        if (path == null) {
            return;
        }
        try {
            Files.deleteIfExists(path);
        } catch (IOException e) {
            log.warn("Could not delete temp file {}", path, e);
        }
    }

    public static class VoiceException extends RuntimeException {
        public VoiceException(String message, Throwable cause) {
            super(message, cause);
        }
        public VoiceException(String message) {
            super(message);
        }
    }
}

package com.feynman.backend.service;

import com.feynman.backend.config.OpenAiProperties;
import com.feynman.backend.dto.VoiceChatResponse;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PreDestroy;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.ByteArrayResource;
import org.springframework.http.MediaType;
import org.springframework.http.client.MultipartBodyBuilder;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientResponseException;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

@Service
public class VoiceChatService {

    private static final Logger log = LoggerFactory.getLogger(VoiceChatService.class);

    private final RestClient openAiRestClient;
    private final OpenAiProperties properties;
    private final ObjectMapper objectMapper = new ObjectMapper();

    /** Runs the learner-transcription call alongside the tutor completion. */
    private final ExecutorService executor =
            Executors.newCachedThreadPool(r -> {
                Thread t = new Thread(r, "voice-transcribe");
                t.setDaemon(true);
                return t;
            });

    public VoiceChatService(RestClient openAiRestClient, OpenAiProperties properties) {
        this.openAiRestClient = openAiRestClient;
        this.properties = properties;
    }

    @PreDestroy
    void shutdown() {
        executor.shutdownNow();
    }

    // gpt-audio only accepts wav and mp3 as input formats
    private static final java.util.Set<String> SUPPORTED_FORMATS = java.util.Set.of("wav", "mp3");

    /** Upper bound on replayed turns, mirroring the client cap, to keep prompts bounded. */
    private static final int MAX_HISTORY_MESSAGES = 20;

    public VoiceChatResponse chat(byte[] audioBytes, String mimeType, String noteText) {
        return chat(audioBytes, mimeType, noteText, null);
    }

    public VoiceChatResponse chat(byte[] audioBytes, String mimeType, String noteText,
                                  String historyJson) {
        String rawFormat = mimeType != null && mimeType.contains("/")
                ? mimeType.substring(mimeType.indexOf('/') + 1).split(";")[0]
                : "wav";
        // m4a arrives as "x-m4a" or "mp4" — treat as mp3-compatible
        String audioFormat = switch (rawFormat) {
            case "mpeg", "x-mpeg", "mp4", "x-m4a", "m4a" -> "mp3";
            default -> rawFormat;
        };

        // gpt-audio rejects ogg/webm outright (browser MediaRecorder output), so transcode via ffmpeg first
        if ("ogg".equals(audioFormat) || "webm".equals(audioFormat)) {
            audioBytes = convertToWav(audioBytes, audioFormat);
            audioFormat = "wav";
        }

        if (!SUPPORTED_FORMATS.contains(audioFormat)) {
            throw new VoiceException(
                    "Unsupported audio format '" + audioFormat + "'. Send wav or mp3.");
        }

        String base64Audio = Base64.getEncoder().encodeToString(audioBytes);

        String systemPrompt = """
                You are a supportive Feynman-technique tutor. The learner will send you a voice \
                explanation of a topic. You have their reference notes below.
                Compare what they said to those notes: praise what they explained correctly, \
                point out any gaps or misconceptions, then ask ONE focused reflection question \
                to deepen their understanding. Keep your response concise and encouraging.
                If earlier turns of this conversation are present, build on them: acknowledge \
                progress since the last turn and avoid repeating feedback you already gave."""
                + "\n\nReference notes:\n" + noteText;

        Map<String, Object> inputAudio = new LinkedHashMap<>();
        inputAudio.put("type", "input_audio");
        inputAudio.put("input_audio", Map.of("data", base64Audio, "format", audioFormat));

        List<Map<String, Object>> messages = new ArrayList<>();
        messages.add(Map.of("role", "system", "content", systemPrompt));
        messages.addAll(parseHistory(historyJson));
        messages.add(Map.of("role", "user", "content", List.of(inputAudio)));

        Map<String, Object> body = new LinkedHashMap<>();
        body.put("model", properties.audioModel());
        body.put("modalities", List.of("text", "audio"));
        body.put("audio", Map.of("voice", "alloy", "format", "wav"));
        body.put("messages", messages);

        try {
            long started = System.nanoTime();

            // The learner's transcript is independent of the tutor's reply, so run both
            // OpenAI calls concurrently instead of paying for two sequential round-trips.
            final byte[] audioForTranscript = audioBytes;
            CompletableFuture<String> transcriptFuture =
                    CompletableFuture.supplyAsync(() -> transcribeAudio(audioForTranscript), executor);

            String responseJson = openAiRestClient.post()
                    .uri("/chat/completions")
                    .contentType(MediaType.APPLICATION_JSON)
                    .body(body)
                    .retrieve()
                    .body(String.class);
            long chatMs = (System.nanoTime() - started) / 1_000_000;

            JsonNode audio = objectMapper.readTree(responseJson)
                    .path("choices").path(0).path("message").path("audio");

            String userTranscript = transcriptFuture.join();
            log.info("Voice chat timings — completion {}ms, total {}ms",
                    chatMs, (System.nanoTime() - started) / 1_000_000);

            String transcript = audio.path("transcript").asText("");
            String audioData  = audio.path("data").asText("");
            return new VoiceChatResponse(userTranscript, transcript, audioData);

        } catch (RestClientResponseException e) {
            String detail = OpenAiEvaluationService.openAiErrorDetail(
                    e.getStatusCode().value(), e.getResponseBodyAsString(), properties.audioModel());
            log.error("Voice chat failed — {} Body: {}", detail, e.getResponseBodyAsString());
            throw new VoiceException(detail, e);
        } catch (Exception e) {
            log.error("Voice chat failed. Cause: {}", e.getMessage());
            throw new VoiceException(
                    "Voice chat failed. Check OPENAI_API_KEY, audio-model, and network configuration.", e);
        }
    }

    /**
     * Separately transcribes the learner's own audio via OpenAI's speech-to-text endpoint.
     * Runs in parallel with the tutor completion; failures degrade to an empty transcript
     * rather than failing the whole request.
     */
    private String transcribeAudio(byte[] wavBytes) {
        try {
            MultipartBodyBuilder builder = new MultipartBodyBuilder();
            builder.part("file", new ByteArrayResource(wavBytes) {
                @Override
                public String getFilename() {
                    return "audio.wav";
                }
            });
            builder.part("model", properties.transcriptionModel());

            String responseJson = openAiRestClient.post()
                    .uri("/audio/transcriptions")
                    .contentType(MediaType.MULTIPART_FORM_DATA)
                    .body(builder.build())
                    .retrieve()
                    .body(String.class);

            return objectMapper.readTree(responseJson).path("text").asText("");
        } catch (Exception e) {
            log.warn("Transcription of learner audio failed: {}", e.getMessage());
            return "";
        }
    }

    /**
     * Parses the client's prior turns into plain text chat messages. Past turns are replayed as
     * text (not audio) to keep the request small — the model only needs what was said, not how.
     * Malformed history is ignored rather than failing the request.
     */
    private List<Map<String, Object>> parseHistory(String historyJson) {
        if (historyJson == null || historyJson.isBlank()) {
            return List.of();
        }
        try {
            JsonNode root = objectMapper.readTree(historyJson);
            if (!root.isArray()) {
                return List.of();
            }
            List<Map<String, Object>> messages = new ArrayList<>();
            for (JsonNode node : root) {
                String role = node.path("role").asText("");
                String text = node.path("text").asText("");
                if (text.isBlank() || !("user".equals(role) || "assistant".equals(role))) {
                    continue;
                }
                messages.add(Map.of("role", role, "content", text));
            }
            // Keep only the most recent exchanges if the client sent more than expected.
            if (messages.size() > MAX_HISTORY_MESSAGES) {
                messages = new ArrayList<>(
                        messages.subList(messages.size() - MAX_HISTORY_MESSAGES, messages.size()));
            }
            return messages;
        } catch (Exception e) {
            log.warn("Ignoring malformed voice chat history: {}", e.getMessage());
            return List.of();
        }
    }

    /** Shells out to the system {@code ffmpeg} binary to transcode ogg/webm audio to PCM WAV. */
    private byte[] convertToWav(byte[] inputBytes, String sourceFormat) {
        Path inputFile = null;
        Path wavFile = null;
        try {
            inputFile = Files.createTempFile("voice-", "." + sourceFormat);
            wavFile = Files.createTempFile("voice-", ".wav");
            Files.write(inputFile, inputBytes);

            Process process = new ProcessBuilder(
                    "ffmpeg", "-y", "-i", inputFile.toString(),
                    "-ar", "24000", "-ac", "1", wavFile.toString())
                    .redirectErrorStream(true)
                    .start();

            if (!process.waitFor(30, TimeUnit.SECONDS)) {
                process.destroyForcibly();
                throw new VoiceException("Audio conversion timed out.");
            }
            if (process.exitValue() != 0) {
                throw new VoiceException("Audio conversion failed (ffmpeg exit code "
                        + process.exitValue() + ").");
            }
            return Files.readAllBytes(wavFile);
        } catch (IOException e) {
            throw new VoiceException(
                    "Could not convert " + sourceFormat + " audio to wav. Is ffmpeg installed and on PATH?", e);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new VoiceException("Audio conversion was interrupted.", e);
        } finally {
            deleteQuietly(inputFile);
            deleteQuietly(wavFile);
        }
    }

    private void deleteQuietly(Path path) {
        if (path == null) {
            return;
        }
        try {
            Files.deleteIfExists(path);
        } catch (IOException e) {
            log.warn("Could not delete temp file {}", path, e);
        }
    }

    public static class VoiceException extends RuntimeException {
        public VoiceException(String message, Throwable cause) {
            super(message, cause);
        }
        public VoiceException(String message) {
            super(message);
        }
    }
}

package com.feynman.backend.service;

import com.feynman.backend.config.OpenAiProperties;
import com.feynman.backend.dto.EvaluateRequest;
import com.feynman.backend.dto.EvaluationResponse;
import com.feynman.backend.dto.NotebookDto;
import com.feynman.backend.dto.PageDto;
import com.feynman.backend.dto.ScoreDto;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Unit tests for the deterministic (mock) scoring path — no API key required.
 */
class OpenAiEvaluationServiceTest {

    private OpenAiEvaluationService newMockService() {
        OpenAiProperties props = new OpenAiProperties("", "gpt-4o-mini",
                "https://api.openai.com/v1", true);
        return new OpenAiEvaluationService(null, props);
    }

    @Test
    void scoresAreDeterministicAndBounded() {
        OpenAiEvaluationService service = newMockService();
        PageDto page = new PageDto("pg-feynman", "nb-study", null,
                "Feynman Technique",
                "Pick a concept, teach it simply, identify gaps, review and simplify.",
                List.of(), 0);

        EvaluateRequest request = new EvaluateRequest(
                List.of(new NotebookDto("nb-study", "Study", "#c94f0c")),
                List.of(page), null);

        EvaluationResponse first = service.evaluate(request);
        EvaluationResponse second = service.evaluate(request);

        ScoreDto pageScore = first.pageScores().get("pg-feynman");
        assertEquals(pageScore.score(), second.pageScores().get("pg-feynman").score(),
                "Mock scoring must be deterministic");
        assertTrue(pageScore.score() >= 0 && pageScore.score() <= 100,
                "Score must be within 0–100");
    }

    @Test
    void notebookScoreAggregatesPages() {
        OpenAiEvaluationService service = newMockService();
        PageDto p1 = new PageDto("pg-1", "nb-1", null, "A", "one two three", List.of(), 0);
        PageDto p2 = new PageDto("pg-2", "nb-1", null, "B", "four five six seven", List.of(), 1);

        EvaluationResponse res = service.evaluate(new EvaluateRequest(
                List.of(new NotebookDto("nb-1", "N", "#000")),
                List.of(p1, p2), null));

        int expected = Math.round(
                (res.pageScores().get("pg-1").score() + res.pageScores().get("pg-2").score()) / 2f);
        assertEquals(expected, res.notebookScores().get("nb-1").score());
    }

    @Test
    void emptyPageScoresZero() {
        OpenAiEvaluationService service = newMockService();
        PageDto empty = new PageDto("pg-empty", "nb-1", null, "Empty", "   ", List.of(), 0);
        EvaluationResponse res = service.evaluate(
                new EvaluateRequest(List.of(), List.of(empty), null));
        assertEquals(0, res.pageScores().get("pg-empty").score());
    }

    @Test
    void notebookIdFilterLimitsScope() {
        OpenAiEvaluationService service = newMockService();
        PageDto a = new PageDto("pg-a", "nb-1", null, "A", "alpha beta gamma", List.of(), 0);
        PageDto b = new PageDto("pg-b", "nb-2", null, "B", "delta epsilon", List.of(), 0);

        EvaluationResponse res = service.evaluate(new EvaluateRequest(
                List.of(new NotebookDto("nb-1", "One", "#000"),
                        new NotebookDto("nb-2", "Two", "#111")),
                List.of(a, b), "nb-1"));

        assertTrue(res.pageScores().containsKey("pg-a"));
        assertTrue(!res.pageScores().containsKey("pg-b"), "Filtered notebook page must be excluded");
        assertTrue(res.notebookScores().containsKey("nb-1"));
        assertTrue(!res.notebookScores().containsKey("nb-2"));
    }

    // --- Mock scoring bands -----------------------------------------------------

    @Test
    void uncertainNotesScoreLow() {
        OpenAiEvaluationService service = newMockService();
        PageDto pythagoras = new PageDto("pg-pythagoras", "nb-math", null,
                "Pythagorean Theorem",
                "Formula is a2 + b2 = c2 or was it a + b = c2? Not sure which side is which. "
                        + "Maybe only right-angled ones?? No idea why it is true. Never understood the proof.",
                List.of(), 0);

        int score = service.mockScore(pythagoras).score();
        assertTrue(score <= 45, "Uncertain notes should score low, was " + score);
    }

    @Test
    void detailedConfidentNotesScoreHigh() {
        OpenAiEvaluationService service = newMockService();
        // Genuinely detailed notes (>120 words) with explanations and no
        // uncertainty — the effort term saturates and evidence bonuses apply.
        String detailed = "Photosynthesis converts light energy into chemical energy because "
                + "chlorophyll in the thylakoid membranes absorbs photons and excites electrons. "
                + "For example, water is split during photolysis which means oxygen is released as a "
                + "by-product while protons build a gradient. That gradient drives ATP synthase, "
                + "therefore ATP and NADPH are produced in the light-dependent reactions. In the "
                + "Calvin cycle the enzyme RuBisCO fixes carbon dioxide onto RuBP, and because the "
                + "ATP and NADPH from the light stage are spent, glucose is gradually assembled. "
                + "This explains how the two stages are coupled and why neither can run alone. "
                + "The overall balance 6 CO2 + 6 H2O = C6H12O6 + 6 O2 summarises the process, and "
                + "this is why photosynthesis underpins food chains and the carbon cycle as a result.";

        int score = service.mockScore(page(detailed)).score();
        assertTrue(score >= 70, "Detailed, confident notes should score high, was " + score);
    }

    private static PageDto page(String content) {
        return new PageDto("pg-detail", "nb-bio", null, "Photosynthesis", content, List.of(), 0);
    }

    @Test
    void uncertainScoresBelowConfident() {
        OpenAiEvaluationService service = newMockService();
        PageDto weak = new PageDto("pg-weak", "n", null, "Weak",
                "not sure, no idea, never understood this at all maybe", List.of(), 0);
        PageDto strong = new PageDto("pg-strong", "n", null, "Strong",
                "This works because the parts connect, for example therefore it follows clearly = yes",
                List.of(), 0);

        assertTrue(service.mockScore(weak).score() < service.mockScore(strong).score(),
                "Uncertain notes must score below confident, explained notes");
    }

    // --- OpenAI error mapping ---------------------------------------------------

    @Test
    void errorMappingProducesActionableMessages() {
        assertTrue(OpenAiEvaluationService.openAiErrorDetail(401, "", "gpt-4o-mini")
                .contains("API key"), "401 should mention the API key");
        assertTrue(OpenAiEvaluationService.openAiErrorDetail(404, "", "gpt-4o-mini")
                .contains("gpt-4o-mini"), "404 should name the model");
        assertTrue(OpenAiEvaluationService.openAiErrorDetail(
                        429, "{\"error\":{\"code\":\"insufficient_quota\"}}", "gpt-4o-mini")
                .toLowerCase().contains("credits"), "429 quota should mention credits");
        assertTrue(OpenAiEvaluationService.openAiErrorDetail(429, "slow down", "gpt-4o-mini")
                .toLowerCase().contains("rate limit"), "429 non-quota should mention rate limit");
        assertTrue(OpenAiEvaluationService.openAiErrorDetail(500, "", "gpt-4o-mini")
                .contains("500"), "Unknown status should include the code");
    }

    // --- Temperature capability -------------------------------------------------

    @Test
    void temperatureOnlySentForSupportedModels() {
        // gpt-5.x and o-series reject an explicit temperature (HTTP 400).
        assertFalse(OpenAiEvaluationService.supportsCustomTemperature("gpt-5.5"));
        assertFalse(OpenAiEvaluationService.supportsCustomTemperature("gpt-5.5-pro"));
        assertFalse(OpenAiEvaluationService.supportsCustomTemperature("o1"));
        assertFalse(OpenAiEvaluationService.supportsCustomTemperature("o3-mini"));
        assertFalse(OpenAiEvaluationService.supportsCustomTemperature("o4-mini"));
        // Older chat models still accept temperature=0 for determinism.
        assertTrue(OpenAiEvaluationService.supportsCustomTemperature("gpt-4o"));
        assertTrue(OpenAiEvaluationService.supportsCustomTemperature("gpt-4o-mini"));
        assertTrue(OpenAiEvaluationService.supportsCustomTemperature("gpt-4.1"));
        assertTrue(OpenAiEvaluationService.supportsCustomTemperature(null));
    }

    // --- Feedback and to-dos ----------------------------------------------------

    @Test
    void mockScoreProducesFeedbackAndTodos() {
        OpenAiEvaluationService service = newMockService();
        PageDto sparse = new PageDto("pg-x", "nb", null, "Topic", "a short note", List.of(), 0);

        ScoreDto s = service.mockScore(sparse);

        assertFalse(s.feedback().isBlank(), "Mock feedback must not be blank");
        assertFalse(s.todos().isEmpty(), "Sparse notes should yield actionable to-dos");
    }

    @Test
    void emptyPageHasFeedbackButNoTodos() {
        OpenAiEvaluationService service = newMockService();
        PageDto empty = new PageDto("pg-empty", "nb", null, "Empty", "   ", List.of(), 0);

        ScoreDto s = service.mockScore(empty);

        assertEquals(0, s.score());
        assertFalse(s.feedback().isBlank(), "Empty page should still explain there is nothing to grade");
        assertTrue(s.todos().isEmpty(), "Empty page should have no to-dos");
    }

    @Test
    void scoreDtoGuaranteesNonNullTodos() {
        ScoreDto s = new ScoreDto(50, "notes", "feedback", null);
        assertTrue(s.todos().isEmpty(), "null todos must normalise to an empty list");
    }

    @Test
    void evaluatePopulatesFeedbackAndTodosViaMock() {
        OpenAiEvaluationService service = newMockService();
        PageDto page = new PageDto("pg-a", "nb-1", null, "A", "brief", List.of(), 0);

        EvaluationResponse res = service.evaluate(new EvaluateRequest(
                List.of(new NotebookDto("nb-1", "N", "#000")), List.of(page), null));

        ScoreDto pageScore = res.pageScores().get("pg-a");
        assertFalse(pageScore.feedback().isBlank());
        assertFalse(pageScore.todos().isEmpty());
        // Notebook aggregation carries feedback but no page-level to-dos.
        assertFalse(res.notebookScores().get("nb-1").feedback().isBlank());
        assertTrue(res.notebookScores().get("nb-1").todos().isEmpty());
    }
}

package com.feynman.backend.service;

import com.feynman.backend.config.OpenAiProperties;
import com.feynman.backend.dto.EvaluateRequest;
import com.feynman.backend.dto.EvaluationResponse;
import com.feynman.backend.dto.NotebookDto;
import com.feynman.backend.dto.PageDto;
import com.feynman.backend.dto.ScoreDto;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Unit tests for the deterministic (mock) scoring path — no API key required.
 */
class OpenAiEvaluationServiceTest {

    private OpenAiEvaluationService newMockService() {
        OpenAiProperties props = new OpenAiProperties("", "gpt-4o-mini",
                "https://api.openai.com/v1", true);
        return new OpenAiEvaluationService(null, props);
    }

    @Test
    void scoresAreDeterministicAndBounded() {
        OpenAiEvaluationService service = newMockService();
        PageDto page = new PageDto("pg-feynman", "nb-study", null,
                "Feynman Technique",
                "Pick a concept, teach it simply, identify gaps, review and simplify.",
                List.of(), 0);

        EvaluateRequest request = new EvaluateRequest(
                List.of(new NotebookDto("nb-study", "Study", "#c94f0c")),
                List.of(page), null);

        EvaluationResponse first = service.evaluate(request);
        EvaluationResponse second = service.evaluate(request);

        ScoreDto pageScore = first.pageScores().get("pg-feynman");
        assertEquals(pageScore.score(), second.pageScores().get("pg-feynman").score(),
                "Mock scoring must be deterministic");
        assertTrue(pageScore.score() >= 0 && pageScore.score() <= 100,
                "Score must be within 0–100");
    }

    @Test
    void notebookScoreAggregatesPages() {
        OpenAiEvaluationService service = newMockService();
        PageDto p1 = new PageDto("pg-1", "nb-1", null, "A", "one two three", List.of(), 0);
        PageDto p2 = new PageDto("pg-2", "nb-1", null, "B", "four five six seven", List.of(), 1);

        EvaluationResponse res = service.evaluate(new EvaluateRequest(
                List.of(new NotebookDto("nb-1", "N", "#000")),
                List.of(p1, p2), null, null));

        int expected = Math.round(
                (res.pageScores().get("pg-1").score() + res.pageScores().get("pg-2").score()) / 2f);
        assertEquals(expected, res.notebookScores().get("nb-1").score());
    }

    @Test
    void emptyPageScoresZero() {
        OpenAiEvaluationService service = newMockService();
        PageDto empty = new PageDto("pg-empty", "nb-1", null, "Empty", "   ", List.of(), 0);
        EvaluationResponse res = service.evaluate(
                new EvaluateRequest(List.of(), List.of(empty), null, null));
        assertEquals(0, res.pageScores().get("pg-empty").score());
    }

    @Test
    void notebookIdFilterLimitsScope() {
        OpenAiEvaluationService service = newMockService();
        PageDto a = new PageDto("pg-a", "nb-1", null, "A", "alpha beta gamma", List.of(), 0);
        PageDto b = new PageDto("pg-b", "nb-2", null, "B", "delta epsilon", List.of(), 0);

        EvaluationResponse res = service.evaluate(new EvaluateRequest(
                List.of(new NotebookDto("nb-1", "One", "#000"),
                        new NotebookDto("nb-2", "Two", "#111")),
                List.of(a, b), "nb-1", null));

        assertTrue(res.pageScores().containsKey("pg-a"));
        assertTrue(!res.pageScores().containsKey("pg-b"), "Filtered notebook page must be excluded");
        assertTrue(res.notebookScores().containsKey("nb-1"));
        assertTrue(!res.notebookScores().containsKey("nb-2"));
    }

    @Test
    void pageIdFilterScoresOnlyThatPageAndSkipsNotebookAggregation() {
        OpenAiEvaluationService service = newMockService();
        // A parent page and two sibling subpages all in the same notebook.
        PageDto parent = new PageDto("pg-parent", "nb-1", null, "Parent", "alpha beta gamma", List.of(), 0);
        PageDto child1 = new PageDto("pg-child-1", "nb-1", "pg-parent", "Child 1", "delta epsilon", List.of(), 0);
        PageDto child2 = new PageDto("pg-child-2", "nb-1", "pg-parent", "Child 2", "zeta eta theta", List.of(), 1);

        EvaluationResponse res = service.evaluate(new EvaluateRequest(
                List.of(new NotebookDto("nb-1", "One", "#000")),
                List.of(parent, child1, child2), "nb-1", "pg-child-1"));

        // Only the requested subpage is scored; parent and sibling are untouched.
        assertTrue(res.pageScores().containsKey("pg-child-1"));
        assertEquals(1, res.pageScores().size(), "Only the requested page should be scored");
        assertFalse(res.pageScores().containsKey("pg-parent"));
        assertFalse(res.pageScores().containsKey("pg-child-2"));

        // Notebook aggregation is skipped so a single page cannot clobber the
        // notebook's real average.
        assertTrue(res.notebookScores().isEmpty(), "Single-page requests must not aggregate notebooks");
    }

    // --- Mock scoring bands -----------------------------------------------------

    @Test
    void uncertainNotesScoreLow() {
        OpenAiEvaluationService service = newMockService();
        PageDto pythagoras = new PageDto("pg-pythagoras", "nb-math", null,
                "Pythagorean Theorem",
                "Formula is a2 + b2 = c2 or was it a + b = c2? Not sure which side is which. "
                        + "Maybe only right-angled ones?? No idea why it is true. Never understood the proof.",
                List.of(), 0);

        int score = service.mockScore(pythagoras).score();
        assertTrue(score <= 45, "Uncertain notes should score low, was " + score);
    }

    @Test
    void detailedConfidentNotesScoreHigh() {
        OpenAiEvaluationService service = newMockService();
        // Genuinely detailed notes (>120 words) with explanations and no
        // uncertainty — the effort term saturates and evidence bonuses apply.
        String detailed = "Photosynthesis converts light energy into chemical energy because "
                + "chlorophyll in the thylakoid membranes absorbs photons and excites electrons. "
                + "For example, water is split during photolysis which means oxygen is released as a "
                + "by-product while protons build a gradient. That gradient drives ATP synthase, "
                + "therefore ATP and NADPH are produced in the light-dependent reactions. In the "
                + "Calvin cycle the enzyme RuBisCO fixes carbon dioxide onto RuBP, and because the "
                + "ATP and NADPH from the light stage are spent, glucose is gradually assembled. "
                + "This explains how the two stages are coupled and why neither can run alone. "
                + "The overall balance 6 CO2 + 6 H2O = C6H12O6 + 6 O2 summarises the process, and "
                + "this is why photosynthesis underpins food chains and the carbon cycle as a result.";

        int score = service.mockScore(page(detailed)).score();
        assertTrue(score >= 70, "Detailed, confident notes should score high, was " + score);
    }

    private static PageDto page(String content) {
        return new PageDto("pg-detail", "nb-bio", null, "Photosynthesis", content, List.of(), 0);
    }

    @Test
    void uncertainScoresBelowConfident() {
        OpenAiEvaluationService service = newMockService();
        PageDto weak = new PageDto("pg-weak", "n", null, "Weak",
                "not sure, no idea, never understood this at all maybe", List.of(), 0);
        PageDto strong = new PageDto("pg-strong", "n", null, "Strong",
                "This works because the parts connect, for example therefore it follows clearly = yes",
                List.of(), 0);

        assertTrue(service.mockScore(weak).score() < service.mockScore(strong).score(),
                "Uncertain notes must score below confident, explained notes");
    }

    // --- OpenAI error mapping ---------------------------------------------------

    @Test
    void errorMappingProducesActionableMessages() {
        assertTrue(OpenAiEvaluationService.openAiErrorDetail(401, "", "gpt-4o-mini")
                .contains("API key"), "401 should mention the API key");
        assertTrue(OpenAiEvaluationService.openAiErrorDetail(404, "", "gpt-4o-mini")
                .contains("gpt-4o-mini"), "404 should name the model");
        assertTrue(OpenAiEvaluationService.openAiErrorDetail(
                        429, "{\"error\":{\"code\":\"insufficient_quota\"}}", "gpt-4o-mini")
                .toLowerCase().contains("credits"), "429 quota should mention credits");
        assertTrue(OpenAiEvaluationService.openAiErrorDetail(429, "slow down", "gpt-4o-mini")
                .toLowerCase().contains("rate limit"), "429 non-quota should mention rate limit");
        assertTrue(OpenAiEvaluationService.openAiErrorDetail(500, "", "gpt-4o-mini")
                .contains("500"), "Unknown status should include the code");
    }

    // --- Temperature capability -------------------------------------------------

    @Test
    void temperatureOnlySentForSupportedModels() {
        // gpt-5.x and o-series reject an explicit temperature (HTTP 400).
        assertFalse(OpenAiEvaluationService.supportsCustomTemperature("gpt-5.5"));
        assertFalse(OpenAiEvaluationService.supportsCustomTemperature("gpt-5.5-pro"));
        assertFalse(OpenAiEvaluationService.supportsCustomTemperature("o1"));
        assertFalse(OpenAiEvaluationService.supportsCustomTemperature("o3-mini"));
        assertFalse(OpenAiEvaluationService.supportsCustomTemperature("o4-mini"));
        // Older chat models still accept temperature=0 for determinism.
        assertTrue(OpenAiEvaluationService.supportsCustomTemperature("gpt-4o"));
        assertTrue(OpenAiEvaluationService.supportsCustomTemperature("gpt-4o-mini"));
        assertTrue(OpenAiEvaluationService.supportsCustomTemperature("gpt-4.1"));
        assertTrue(OpenAiEvaluationService.supportsCustomTemperature(null));
    }

    // --- Feedback and to-dos ----------------------------------------------------

    @Test
    void mockScoreProducesFeedbackAndTodos() {
        OpenAiEvaluationService service = newMockService();
        PageDto sparse = new PageDto("pg-x", "nb", null, "Topic", "a short note", List.of(), 0);

        ScoreDto s = service.mockScore(sparse);

        assertFalse(s.feedback().isBlank(), "Mock feedback must not be blank");
        assertFalse(s.todos().isEmpty(), "Sparse notes should yield actionable to-dos");
    }

    @Test
    void emptyPageHasFeedbackButNoTodos() {
        OpenAiEvaluationService service = newMockService();
        PageDto empty = new PageDto("pg-empty", "nb", null, "Empty", "   ", List.of(), 0);

        ScoreDto s = service.mockScore(empty);

        assertEquals(0, s.score());
        assertFalse(s.feedback().isBlank(), "Empty page should still explain there is nothing to grade");
        assertTrue(s.todos().isEmpty(), "Empty page should have no to-dos");
    }

    @Test
    void scoreDtoGuaranteesNonNullTodos() {
        ScoreDto s = new ScoreDto(50, "notes", "feedback", null);
        assertTrue(s.todos().isEmpty(), "null todos must normalise to an empty list");
    }

    @Test
    void evaluatePopulatesFeedbackAndTodosViaMock() {
        OpenAiEvaluationService service = newMockService();
        PageDto page = new PageDto("pg-a", "nb-1", null, "A", "brief", List.of(), 0);

        EvaluationResponse res = service.evaluate(new EvaluateRequest(
                List.of(new NotebookDto("nb-1", "N", "#000")), List.of(page), null, null));

        ScoreDto pageScore = res.pageScores().get("pg-a");
        assertFalse(pageScore.feedback().isBlank());
        assertFalse(pageScore.todos().isEmpty());
        // Notebook aggregation carries feedback but no page-level to-dos.
        assertFalse(res.notebookScores().get("nb-1").feedback().isBlank());
        assertTrue(res.notebookScores().get("nb-1").todos().isEmpty());
    }
}

package com.feynman.backend.service;

import com.feynman.backend.config.OpenAiProperties;
import com.feynman.backend.dto.VoiceChatResponse;
import com.feynman.backend.service.VoiceChatService.VoiceException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.web.client.HttpClientErrorException;
import org.springframework.web.client.RestClient;

import java.nio.charset.StandardCharsets;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

@SuppressWarnings({"unchecked", "rawtypes"})
@ExtendWith(MockitoExtension.class)
class VoiceChatServiceTest {

    @Mock private RestClient restClient;
    @Mock private RestClient.RequestBodyUriSpec postSpec;
    // RequestBodySpec extends RequestHeadersSpec<RequestBodySpec> — serves both roles
    @Mock private RestClient.RequestBodySpec bodySpec;
    @Mock private RestClient.ResponseSpec responseSpec;

    private VoiceChatService service;

    private static final OpenAiProperties PROPS = new OpenAiProperties(
            "sk-test", "gpt-audio", "gpt-audio", "gpt-4o-mini-transcribe", "https://api.openai.com/v1", false);

    private static final byte[] AUDIO = "fake-audio".getBytes(StandardCharsets.UTF_8);

    private static final String VALID_RESPONSE = """
            {
              "choices": [{
                "message": {
                  "audio": {
                    "transcript": "Great explanation of photosynthesis.",
                    "data": "dGVzdA=="
                  }
                }
              }]
            }
            """;

    private static final String TRANSCRIPTION_RESPONSE = """
            { "text": "Napoleon was the king." }
            """;

    @BeforeEach
    void setUp() {
        service = new VoiceChatService(restClient, PROPS);
        // lenient: unsupported-format tests throw before the chain is entered
        lenient().when(restClient.post()).thenReturn(postSpec);
        lenient().when(postSpec.uri(anyString())).thenReturn(bodySpec);
        lenient().when(bodySpec.contentType(any())).thenReturn(bodySpec);
        lenient().doReturn(bodySpec).when(bodySpec).body(any(Object.class));
        lenient().when(bodySpec.retrieve()).thenReturn(responseSpec);
    }

    // --- format validation --------------------------------------------------

    @ParameterizedTest
    @ValueSource(strings = {"audio/aiff", "audio/flac"})
    void unsupportedFormatThrowsBeforeHttpCall(String mimeType) {
        // exception thrown before any RestClient call — no stub needed
        assertThrows(VoiceException.class,
                () -> service.chat(AUDIO, mimeType, "some notes"));
    }

    @ParameterizedTest
    @ValueSource(strings = {"audio/wav", "audio/mp3", "audio/mpeg", "audio/mp4", "audio/x-m4a"})
    void supportedFormatReachesOpenAi(String mimeType) {
        stubSuccess();
        assertDoesNotThrow(() -> service.chat(AUDIO, mimeType, "notes"));
    }

    // --- successful response ------------------------------------------------

    @Test
    void successfulResponseMapsTranscriptAndAudioData() {
        stubSuccess();
        VoiceChatResponse res = service.chat(AUDIO, "audio/wav", "notes about photosynthesis");
        assertEquals("Great explanation of photosynthesis.", res.transcript());
        assertEquals("dGVzdA==", res.audioData());
    }

    @Test
    void successfulResponseMapsUserTranscript() {
        // chat/completions and audio/transcriptions are called in that order
        when(responseSpec.body(String.class)).thenReturn(VALID_RESPONSE, TRANSCRIPTION_RESPONSE);
        VoiceChatResponse res = service.chat(AUDIO, "audio/wav", "notes");
        assertEquals("Napoleon was the king.", res.userTranscript());
    }

    @Test
    void nullMimeTypeFallsBackToWav() {
        stubSuccess();
        assertDoesNotThrow(() -> service.chat(AUDIO, null, "notes"));
    }

    // --- OpenAI error handling ----------------------------------------------

    @Test
    void openAi401WrappedInVoiceException() {
        stubHttpError(HttpStatus.UNAUTHORIZED, "{\"error\":{\"message\":\"invalid key\"}}");
        VoiceException ex = assertThrows(VoiceException.class,
                () -> service.chat(AUDIO, "audio/wav", "notes"));
        assertTrue(ex.getMessage().contains("401"));
    }

    @Test
    void openAi429WrappedInVoiceException() {
        stubHttpError(HttpStatus.TOO_MANY_REQUESTS, "{\"error\":{\"message\":\"rate limit\"}}");
        VoiceException ex = assertThrows(VoiceException.class,
                () -> service.chat(AUDIO, "audio/wav", "notes"));
        assertTrue(ex.getMessage().contains("429") || ex.getMessage().contains("rate limit"));
    }

    // --- helpers ------------------------------------------------------------

    private void stubSuccess() {
        when(responseSpec.body(String.class)).thenReturn(VALID_RESPONSE);
    }

    private void stubHttpError(HttpStatus status, String body) {
        when(responseSpec.body(String.class)).thenThrow(
                HttpClientErrorException.create(
                        status, status.getReasonPhrase(),
                        new HttpHeaders(), body.getBytes(StandardCharsets.UTF_8),
                        StandardCharsets.UTF_8));
    }
}

package com.feynman.backend.service;

import com.feynman.backend.config.OpenAiProperties;
import com.feynman.backend.dto.VoiceChatResponse;
import com.feynman.backend.service.VoiceChatService.VoiceException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.web.client.HttpClientErrorException;
import org.springframework.web.client.RestClient;

import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.verify;

@SuppressWarnings("unchecked")
@ExtendWith(MockitoExtension.class)
class VoiceChatServiceTest {

    private static final String CHAT_URI = "/chat/completions";
    private static final String TRANSCRIBE_URI = "/audio/transcriptions";

    @Mock private RestClient restClient;
    @Mock private RestClient.RequestBodyUriSpec postSpec;
    // RequestBodySpec extends RequestHeadersSpec<RequestBodySpec> — serves both roles.
    // The two endpoints get their own spec chains so stubbing does not depend on call
    // order: the completion and the transcription are issued concurrently.
    @Mock private RestClient.RequestBodySpec chatBodySpec;
    @Mock private RestClient.RequestBodySpec transcribeBodySpec;
    @Mock private RestClient.ResponseSpec chatResponseSpec;
    @Mock private RestClient.ResponseSpec transcribeResponseSpec;

    private VoiceChatService service;

    private static final OpenAiProperties PROPS = new OpenAiProperties(
            "sk-test", "gpt-audio", "gpt-audio", "gpt-4o-mini-transcribe", "https://api.openai.com/v1", false);

    private static final byte[] AUDIO = "fake-audio".getBytes(StandardCharsets.UTF_8);

    private static final String VALID_RESPONSE = """
            {
              "choices": [{
                "message": {
                  "audio": {
                    "transcript": "Great explanation of photosynthesis.",
                    "data": "dGVzdA=="
                  }
                }
              }]
            }
            """;

    private static final String TRANSCRIPTION_RESPONSE = """
            { "text": "Napoleon was the king." }
            """;

    @BeforeEach
    void setUp() {
        service = new VoiceChatService(restClient, PROPS);
        // lenient: unsupported-format tests throw before the chain is entered
        lenient().when(restClient.post()).thenReturn(postSpec);
        lenient().when(postSpec.uri(CHAT_URI)).thenReturn(chatBodySpec);
        lenient().when(postSpec.uri(TRANSCRIBE_URI)).thenReturn(transcribeBodySpec);

        lenient().when(chatBodySpec.contentType(any())).thenReturn(chatBodySpec);
        lenient().doReturn(chatBodySpec).when(chatBodySpec).body(any(Object.class));
        lenient().when(chatBodySpec.retrieve()).thenReturn(chatResponseSpec);
        lenient().when(chatResponseSpec.body(String.class)).thenReturn(VALID_RESPONSE);

        lenient().when(transcribeBodySpec.contentType(any())).thenReturn(transcribeBodySpec);
        lenient().doReturn(transcribeBodySpec).when(transcribeBodySpec).body(any(Object.class));
        lenient().when(transcribeBodySpec.retrieve()).thenReturn(transcribeResponseSpec);
        lenient().when(transcribeResponseSpec.body(String.class)).thenReturn(TRANSCRIPTION_RESPONSE);
    }

    // --- format validation --------------------------------------------------

    @ParameterizedTest
    @ValueSource(strings = {"audio/aiff", "audio/flac"})
    void unsupportedFormatThrowsBeforeHttpCall(String mimeType) {
        // exception thrown before any RestClient call — no stub needed
        assertThrows(VoiceException.class,
                () -> service.chat(AUDIO, mimeType, "some notes"));
    }

    @ParameterizedTest
    @ValueSource(strings = {"audio/wav", "audio/mp3", "audio/mpeg", "audio/mp4", "audio/x-m4a"})
    void supportedFormatReachesOpenAi(String mimeType) {
        assertDoesNotThrow(() -> service.chat(AUDIO, mimeType, "notes"));
    }

    // --- successful response ------------------------------------------------

    @Test
    void successfulResponseMapsTranscriptAndAudioData() {
        VoiceChatResponse res = service.chat(AUDIO, "audio/wav", "notes about photosynthesis");
        assertEquals("Great explanation of photosynthesis.", res.transcript());
        assertEquals("dGVzdA==", res.audioData());
    }

    @Test
    void successfulResponseMapsUserTranscript() {
        VoiceChatResponse res = service.chat(AUDIO, "audio/wav", "notes");
        assertEquals("Napoleon was the king.", res.userTranscript());
    }

    @Test
    void nullMimeTypeFallsBackToWav() {
        assertDoesNotThrow(() -> service.chat(AUDIO, null, "notes"));
    }

    /** The learner transcript is a nice-to-have; losing it must not waste the completion. */
    @Test
    void transcriptionFailureDegradesToEmptyTranscriptWithoutFailingRequest() {
        lenient().when(transcribeResponseSpec.body(String.class))
                .thenThrow(HttpClientErrorException.create(
                        HttpStatus.SERVICE_UNAVAILABLE, "unavailable",
                        new HttpHeaders(), new byte[0], StandardCharsets.UTF_8));

        VoiceChatResponse res = service.chat(AUDIO, "audio/wav", "notes");

        assertEquals("", res.userTranscript());
        assertEquals("Great explanation of photosynthesis.", res.transcript());
    }

    // --- conversation history -----------------------------------------------

    @Test
    void historyIsReplayedBetweenSystemPromptAndCurrentAudio() {
        String history = """
                [{"role":"user","text":"Photosynthesis makes sugar."},
                 {"role":"assistant","text":"Good. What supplies the energy?"}]
                """;

        service.chat(AUDIO, "audio/wav", "notes", history);

        List<Map<String, Object>> messages = capturedMessages();
        assertEquals(4, messages.size());
        assertEquals("system", messages.get(0).get("role"));
        assertEquals("user", messages.get(1).get("role"));
        assertEquals("Photosynthesis makes sugar.", messages.get(1).get("content"));
        assertEquals("assistant", messages.get(2).get("role"));
        assertEquals("Good. What supplies the energy?", messages.get(2).get("content"));
        // the freshly recorded audio is always last
        assertEquals("user", messages.get(3).get("role"));
        assertInstanceOf(List.class, messages.get(3).get("content"));
    }

    @Test
    void nullHistorySendsOnlySystemAndAudioMessages() {
        service.chat(AUDIO, "audio/wav", "notes", null);
        assertEquals(2, capturedMessages().size());
    }

    @Test
    void malformedHistoryIsIgnoredRatherThanFailing() {
        assertDoesNotThrow(() -> service.chat(AUDIO, "audio/wav", "notes", "not-json"));
        assertEquals(2, capturedMessages().size());
    }

    @Test
    void historyEntriesWithUnknownRolesOrBlankTextAreSkipped() {
        String history = """
                [{"role":"system","text":"ignore me"},
                 {"role":"user","text":""},
                 {"role":"assistant","text":"kept"}]
                """;

        service.chat(AUDIO, "audio/wav", "notes", history);

        List<Map<String, Object>> messages = capturedMessages();
        assertEquals(3, messages.size());
        assertEquals("kept", messages.get(1).get("content"));
    }

    /** Prompts must stay bounded even if a client ignores its own retention cap. */
    @Test
    void historyIsTruncatedToTheMostRecentMessages() {
        StringBuilder json = new StringBuilder("[");
        for (int i = 0; i < 40; i++) {
            if (i > 0) json.append(',');
            json.append("{\"role\":\"user\",\"text\":\"turn-").append(i).append("\"}");
        }
        json.append(']');

        service.chat(AUDIO, "audio/wav", "notes", json.toString());

        List<Map<String, Object>> messages = capturedMessages();
        // system + 20 retained history messages + current audio
        assertEquals(22, messages.size());
        assertEquals("turn-20", messages.get(1).get("content"));
        assertEquals("turn-39", messages.get(20).get("content"));
    }

    // --- OpenAI error handling ----------------------------------------------

    @Test
    void openAi401WrappedInVoiceException() {
        stubChatHttpError(HttpStatus.UNAUTHORIZED, "{\"error\":{\"message\":\"invalid key\"}}");
        VoiceException ex = assertThrows(VoiceException.class,
                () -> service.chat(AUDIO, "audio/wav", "notes"));
        assertTrue(ex.getMessage().contains("401"));
    }

    @Test
    void openAi429WrappedInVoiceException() {
        stubChatHttpError(HttpStatus.TOO_MANY_REQUESTS, "{\"error\":{\"message\":\"rate limit\"}}");
        VoiceException ex = assertThrows(VoiceException.class,
                () -> service.chat(AUDIO, "audio/wav", "notes"));
        assertTrue(ex.getMessage().contains("429") || ex.getMessage().contains("rate limit"));
    }

    // --- helpers ------------------------------------------------------------

    /** Pulls the "messages" array out of the JSON body sent to /chat/completions. */
    private List<Map<String, Object>> capturedMessages() {
        ArgumentCaptor<Object> captor = ArgumentCaptor.forClass(Object.class);
        verify(chatBodySpec).body(captor.capture());
        Map<String, Object> body = (Map<String, Object>) captor.getValue();
        return (List<Map<String, Object>>) body.get("messages");
    }

    private void stubChatHttpError(HttpStatus status, String body) {
        lenient().when(chatResponseSpec.body(String.class)).thenThrow(
                HttpClientErrorException.create(
                        status, status.getReasonPhrase(),
                        new HttpHeaders(), body.getBytes(StandardCharsets.UTF_8),
                        StandardCharsets.UTF_8));
    }
}

import type { Notebook, Page } from '@/types'
import { evaluateNotes } from '@/services/evaluationApi'
import type { EvaluationResult } from '@/services/evaluationApi'

/**
 * @deprecated Use `@/services/evaluationApi` directly.
 *
 * Kept as a thin re-export so any existing imports of `@/api/evaluation`
 * continue to resolve to the single canonical client.
 */
export type { Score, EvaluationResult } from '@/services/evaluationApi'
export { evaluateNotes } from '@/services/evaluationApi'

/** @deprecated Prefer `evaluateNotes(notebooks, pages, notebookId?)`. */
export async function evaluateNotebooks(payload: {
