import { describe, it, expect, beforeEach, vi } from 'vitest'
import { mount } from '@vue/test-utils'
import { nextTick } from 'vue'
import FormatMenu from '@/components/FormatMenu.vue'

// jsdom implements neither execCommand nor queryCommandState, so we stub them
// and assert against the spies. queryCommandState defaults to false unless a
// test overrides it (used for the active-state assertions below).
let execCommand: ReturnType<typeof vi.fn>
let queryCommandState: ReturnType<typeof vi.fn>

beforeEach(() => {
  execCommand = vi.fn().mockReturnValue(true)
  queryCommandState = vi.fn().mockReturnValue(false)
  // @ts-expect-error - not present in jsdom's Document typings
  document.execCommand = execCommand
  // @ts-expect-error - not present in jsdom's Document typings
  document.queryCommandState = queryCommandState
})

const props = { x: 100, y: 100 }

describe('FormatMenu', () => {
  describe('accessibility roles', () => {
    it('exposes a menu role with an accessible label', () => {
      const wrapper = mount(FormatMenu, { props })
      const menu = wrapper.get('[role="menu"]')
      expect(menu.attributes('aria-label')).toBe('Text formatting')
    })

    it('labels the inline-formatting group', () => {
      const wrapper = mount(FormatMenu, { props })
      const group = wrapper.get('[aria-label="Inline formatting"]')
      expect(group.attributes('role')).toBe('group')
    })

    it('marks list items with the menuitem role', () => {
      const wrapper = mount(FormatMenu, { props })
      expect(wrapper.findAll('[role="menuitem"]').length).toBeGreaterThan(0)
    })
  })

  describe('formatting commands', () => {
    it('runs the bold command and emits "applied" when Bold is clicked', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="Bold"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('bold', false, undefined)
      expect(wrapper.emitted('applied')).toBeTruthy()
    })

    it('forces CSS styling for colour commands', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="No text colour"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('styleWithCSS', false, 'true')
      expect(execCommand).toHaveBeenCalledWith('foreColor', false, '#242424')
    })

    it('applies a highlight colour via hiliteColor', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="No highlight"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('hiliteColor', false, 'transparent')
    })

    it('prompts for and normalises a link URL', async () => {
      const promptSpy = vi.spyOn(window, 'prompt').mockReturnValue('example.com')
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[title="Insert link (Ctrl+K)"]').trigger('click')
      expect(promptSpy).toHaveBeenCalled()
      expect(execCommand).toHaveBeenCalledWith('createLink', false, 'https://example.com')
    })
  })

  describe('active-state indicators', () => {
    it('reflects the current selection state via aria-pressed and .active', async () => {
      queryCommandState.mockImplementation((cmd: string) => cmd === 'bold')
      const wrapper = mount(FormatMenu, { props })
      await nextTick()
      const bold = wrapper.get('[aria-label="Bold"]')
      expect(bold.attributes('aria-pressed')).toBe('true')
      expect(bold.classes()).toContain('active')

      const italic = wrapper.get('[aria-label="Italic"]')
      expect(italic.attributes('aria-pressed')).toBe('false')
      expect(italic.classes()).not.toContain('active')
    })
  })

  describe('keyboard shortcuts', () => {
    it('runs bold on Ctrl+B', () => {
      mount(FormatMenu, { props, attachTo: document.body })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'b', ctrlKey: true }))
      expect(execCommand).toHaveBeenCalledWith('bold', false, undefined)
    })

    it('runs strikethrough only with the Shift modifier on Ctrl+Shift+X', () => {
      mount(FormatMenu, { props, attachTo: document.body })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'x', ctrlKey: true }))
      expect(execCommand).not.toHaveBeenCalledWith('strikeThrough', false, undefined)

      window.dispatchEvent(
        new KeyboardEvent('keydown', { key: 'x', ctrlKey: true, shiftKey: true })
      )
      expect(execCommand).toHaveBeenCalledWith('strikeThrough', false, undefined)
    })

    it('emits "close" on Escape', () => {
      const wrapper = mount(FormatMenu, { props })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }))
      expect(wrapper.emitted('close')).toBeTruthy()
    })

    it('ignores shortcut keys without a modifier', () => {
      mount(FormatMenu, { props })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'b' }))
      expect(execCommand).not.toHaveBeenCalledWith('bold', false, undefined)
    })
  })

  describe('selection preservation', () => {
    it('prevents default on mousedown so the selection is not stolen', async () => {
      const wrapper = mount(FormatMenu, { props })
      const event = new MouseEvent('mousedown', { cancelable: true, bubbles: true })
      wrapper.get('[role="menu"]').element.dispatchEvent(event)
      expect(event.defaultPrevented).toBe(true)
    })
  })

  describe('lifecycle', () => {
    it('stops listening for selection changes after unmount', async () => {
      const removeSpy = vi.spyOn(document, 'removeEventListener')
      const wrapper = mount(FormatMenu, { props })
      await nextTick()
      wrapper.unmount()
      expect(removeSpy).toHaveBeenCalledWith('selectionchange', expect.any(Function))
    })
  })
})

import { describe, it, expect, beforeEach, vi } from 'vitest'
import { mount } from '@vue/test-utils'
import { nextTick } from 'vue'
import FormatMenu from '@/components/FormatMenu.vue'

// jsdom implements neither execCommand nor queryCommandState, so we stub them
// and assert against the spies. queryCommandState defaults to false unless a
// test overrides it (used for the active-state assertions below).
let execCommand: ReturnType<typeof vi.fn>
let queryCommandState: ReturnType<typeof vi.fn>

beforeEach(() => {
  execCommand = vi.fn().mockReturnValue(true)
  queryCommandState = vi.fn().mockReturnValue(false)
  document.execCommand = execCommand as unknown as typeof document.execCommand
  document.queryCommandState =
    queryCommandState as unknown as typeof document.queryCommandState
})

const props = { x: 100, y: 100 }

describe('FormatMenu', () => {
  describe('accessibility roles', () => {
    it('exposes a menu role with an accessible label', () => {
      const wrapper = mount(FormatMenu, { props })
      const menu = wrapper.get('[role="menu"]')
      expect(menu.attributes('aria-label')).toBe('Text formatting')
    })

    it('labels the inline-formatting group', () => {
      const wrapper = mount(FormatMenu, { props })
      const group = wrapper.get('[aria-label="Inline formatting"]')
      expect(group.attributes('role')).toBe('group')
    })

    it('marks list items with the menuitem role', () => {
      const wrapper = mount(FormatMenu, { props })
      expect(wrapper.findAll('[role="menuitem"]').length).toBeGreaterThan(0)
    })
  })

  describe('formatting commands', () => {
    it('runs the bold command and emits "applied" when Bold is clicked', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="Bold"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('bold', false, undefined)
      expect(wrapper.emitted('applied')).toBeTruthy()
    })

    it('forces CSS styling for colour commands', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="No text colour"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('styleWithCSS', false, 'true')
      expect(execCommand).toHaveBeenCalledWith('foreColor', false, '#242424')
    })

    it('applies a highlight colour via hiliteColor', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="No highlight"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('hiliteColor', false, 'transparent')
    })

    it('prompts for and normalises a link URL', async () => {
      const promptSpy = vi.spyOn(window, 'prompt').mockReturnValue('example.com')
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[title="Insert link (Ctrl+K)"]').trigger('click')
      expect(promptSpy).toHaveBeenCalled()
      expect(execCommand).toHaveBeenCalledWith('createLink', false, 'https://example.com')
    })
  })

  describe('active-state indicators', () => {
    it('reflects the current selection state via aria-pressed and .active', async () => {
      queryCommandState.mockImplementation((cmd: string) => cmd === 'bold')
      const wrapper = mount(FormatMenu, { props })
      await nextTick()
      const bold = wrapper.get('[aria-label="Bold"]')
      expect(bold.attributes('aria-pressed')).toBe('true')
      expect(bold.classes()).toContain('active')

      const italic = wrapper.get('[aria-label="Italic"]')
      expect(italic.attributes('aria-pressed')).toBe('false')
      expect(italic.classes()).not.toContain('active')
    })
  })

  describe('keyboard shortcuts', () => {
    it('runs bold on Ctrl+B', () => {
      mount(FormatMenu, { props, attachTo: document.body })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'b', ctrlKey: true }))
      expect(execCommand).toHaveBeenCalledWith('bold', false, undefined)
    })

    it('runs strikethrough only with the Shift modifier on Ctrl+Shift+X', () => {
      mount(FormatMenu, { props, attachTo: document.body })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'x', ctrlKey: true }))
      expect(execCommand).not.toHaveBeenCalledWith('strikeThrough', false, undefined)

      window.dispatchEvent(
        new KeyboardEvent('keydown', { key: 'x', ctrlKey: true, shiftKey: true })
      )
      expect(execCommand).toHaveBeenCalledWith('strikeThrough', false, undefined)
    })

    it('emits "close" on Escape', () => {
      const wrapper = mount(FormatMenu, { props })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }))
      expect(wrapper.emitted('close')).toBeTruthy()
    })

    it('ignores shortcut keys without a modifier', () => {
      mount(FormatMenu, { props })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'b' }))
      expect(execCommand).not.toHaveBeenCalledWith('bold', false, undefined)
    })
  })

  describe('selection preservation', () => {
    it('prevents default on mousedown so the selection is not stolen', async () => {
      const wrapper = mount(FormatMenu, { props })
      const event = new MouseEvent('mousedown', { cancelable: true, bubbles: true })
      wrapper.get('[role="menu"]').element.dispatchEvent(event)
      expect(event.defaultPrevented).toBe(true)
    })
  })

  describe('lifecycle', () => {
    it('stops listening for selection changes after unmount', async () => {
      const removeSpy = vi.spyOn(document, 'removeEventListener')
      const wrapper = mount(FormatMenu, { props })
      await nextTick()
      wrapper.unmount()
      expect(removeSpy).toHaveBeenCalledWith('selectionchange', expect.any(Function))
    })
  })
})

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { mount, flushPromises, type VueWrapper } from '@vue/test-utils'
import VoiceChat from '@/components/VoiceChat.vue'
import { sendVoiceMessage } from '@/services/voiceApi'
import type { VoiceHistoryMessage } from '@/types'

vi.mock('@/services/voiceApi', () => ({
  sendVoiceMessage: vi.fn()
}))

const mockedSend = vi.mocked(sendVoiceMessage)

/**
 * Minimal MediaRecorder stand-in: `stop()` synchronously fires `onstop`, which
 * is what triggers the backend request in the component.
 */
class FakeMediaRecorder {
  static isTypeSupported = () => true

  ondataavailable: ((e: { data: Blob }) => void) | null = null
  onstop: (() => void) | null = null
  mimeType = 'audio/webm'

  start() {
    this.ondataavailable?.({ data: new Blob(['x'], { type: 'audio/webm' }) })
  }

  stop() {
    this.onstop?.()
  }
}

function reply(n: number) {
  return {
    userTranscript: `learner ${n}`,
    transcript: `tutor ${n}`,
    audioData: ''
  }
}

/**
 * Performs one full hold-to-record gesture and waits for the request to settle.
 * Uses the real mousedown/mouseup path so `stopRecording` (and its timer
 * cleanup) is exercised rather than bypassed.
 */
async function record(wrapper: VueWrapper) {
  const button = wrapper.find('.record-btn')
  await button.trigger('mousedown')
  await flushPromises() // getUserMedia resolves, recorder starts
  await button.trigger('mouseup')
  await flushPromises() // sendVoiceMessage resolves
}

describe('VoiceChat', () => {
  beforeEach(() => {
    mockedSend.mockReset()

    vi.stubGlobal('MediaRecorder', FakeMediaRecorder)
    // Patch only mediaDevices — replacing all of `navigator` breaks jsdom internals.
    Object.defineProperty(globalThis.navigator, 'mediaDevices', {
      value: { getUserMedia: vi.fn().mockResolvedValue({ getTracks: () => [] }) },
      configurable: true,
      writable: true
    })
    // jsdom has no audio stack; playback is irrelevant to the retention logic.
    vi.stubGlobal(
      'Audio',
      class {
        play = vi.fn().mockResolvedValue(undefined)
      }
    )
  })

  afterEach(() => {
    vi.unstubAllGlobals()
  })

  it('keeps previous turns when a new recording is made', async () => {
    mockedSend.mockResolvedValueOnce(reply(1)).mockResolvedValueOnce(reply(2))
    const wrapper = mount(VoiceChat, { props: { noteText: 'notes' } })

    await record(wrapper)
    await record(wrapper)

    const text = wrapper.text()
    expect(text).toContain('learner 1')
    expect(text).toContain('tutor 1')
    expect(text).toContain('learner 2')
    expect(text).toContain('tutor 2')
    expect(wrapper.findAll('.voice-bubble')).toHaveLength(4)
  })

  it('sends prior turns as history so the tutor keeps context', async () => {
    mockedSend.mockResolvedValueOnce(reply(1)).mockResolvedValueOnce(reply(2))
    const wrapper = mount(VoiceChat, { props: { noteText: 'notes' } })

    await record(wrapper)
    await record(wrapper)

    // First call starts cold, second replays the completed exchange.
    expect(mockedSend.mock.calls[0][2]).toEqual([])
    expect(mockedSend.mock.calls[1][2]).toEqual<VoiceHistoryMessage[]>([
      { role: 'user', text: 'learner 1' },
      { role: 'assistant', text: 'tutor 1' }
    ])
  })

  it('retains at most 10 exchanges, dropping the oldest', async () => {
    for (let i = 1; i <= 12; i++) {
      mockedSend.mockResolvedValueOnce(reply(i))
    }
    const wrapper = mount(VoiceChat, { props: { noteText: 'notes' } })

    for (let i = 0; i < 12; i++) {
      await record(wrapper)
    }

    expect(wrapper.findAll('.voice-bubble')).toHaveLength(20) // 10 turns x 2 bubbles
    // Turns 1 and 2 fell out of the window; 3-12 remain.
    expect(wrapper.text()).not.toContain('tutor 2')
    expect(wrapper.text()).toContain('tutor 3')
    expect(wrapper.text()).toContain('tutor 12')
  })

  it('clears the conversation on demand', async () => {
    mockedSend.mockResolvedValueOnce(reply(1))
    const wrapper = mount(VoiceChat, { props: { noteText: 'notes' } })

    await record(wrapper)
    expect(wrapper.findAll('.voice-bubble')).toHaveLength(2)

    await wrapper.find('.clear-btn').trigger('click')
    expect(wrapper.findAll('.voice-bubble')).toHaveLength(0)
    expect(wrapper.find('.voice-dialog').exists()).toBe(false)
  })

  it('keeps earlier turns visible when a request fails', async () => {
    mockedSend.mockResolvedValueOnce(reply(1)).mockRejectedValueOnce(new Error('boom'))
    const wrapper = mount(VoiceChat, { props: { noteText: 'notes' } })

    await record(wrapper)
    await record(wrapper)

    expect(wrapper.find('.voice-error').text()).toBe('boom')
    expect(wrapper.text()).toContain('tutor 1')
    expect(wrapper.findAll('.voice-bubble')).toHaveLength(2)
  })
})

import type { VoiceChatResponse } from '@/types'
import { apiFetch } from './httpClient'

/**
 * Client for the Feynman backend voice chat API.
 *
 * Requests are authenticated (bearer token) via {@link apiFetch}.
 */

/**
 * Send a recorded explanation (audio) plus the reference note text to the
 * backend, which asks OpenAI to compare them and reply with spoken feedback.
 */
export async function sendVoiceMessage(
  audioBlob: Blob,
  noteText: string
): Promise<VoiceChatResponse> {
  // A filename is required so the backend receives a well-formed file part
  // (and the extension keeps the format recognisable server-side).
  const extension = (audioBlob.type.split('/')[1] ?? 'webm').split(';')[0]

  const formData = new FormData()
  formData.append('audio', audioBlob, `recording.${extension}`)
  formData.append('noteText', noteText)

  const res = await apiFetch('/api/voice/chat', {
    method: 'POST',
    body: formData
  })

  if (!res.ok) {
    const problem = await res.json().catch(() => null)
    const detail = problem?.detail ?? `${res.status} ${res.statusText}`
    throw new Error(`Voice chat request failed: ${detail}`)
  }

  return (await res.json()) as VoiceChatResponse
}

import type { VoiceChatResponse, VoiceHistoryMessage } from '@/types'
import { apiFetch } from './httpClient'

/**
 * Client for the Feynman backend voice chat API.
 *
 * Requests are authenticated (bearer token) via {@link apiFetch}.
 */

/**
 * Send a recorded explanation (audio) plus the reference note text to the
 * backend, which asks OpenAI to compare them and reply with spoken feedback.
 *
 * @param history Previous turns of the session, so the tutor can follow up on
 *                what was already discussed instead of starting cold each time.
 */
export async function sendVoiceMessage(
  audioBlob: Blob,
  noteText: string,
  history: VoiceHistoryMessage[] = []
): Promise<VoiceChatResponse> {
  // A filename is required so the backend receives a well-formed file part
  // (and the extension keeps the format recognisable server-side).
  const extension = (audioBlob.type.split('/')[1] ?? 'webm').split(';')[0]

  const formData = new FormData()
  formData.append('audio', audioBlob, `recording.${extension}`)
  formData.append('noteText', noteText)
  if (history.length > 0) {
    formData.append('history', JSON.stringify(history))
  }

  const res = await apiFetch('/api/voice/chat', {
    method: 'POST',
    body: formData
  })

  if (!res.ok) {
    const problem = await res.json().catch(() => null)
    const detail = problem?.detail ?? `${res.status} ${res.statusText}`
    throw new Error(`Voice chat request failed: ${detail}`)
  }

  return (await res.json()) as VoiceChatResponse
}

import { describe, it, expect, beforeEach, vi } from 'vitest'
import { createPinia, setActivePinia } from 'pinia'
import type { Notebook, Page } from '@/types'
import type { EvaluationResult } from '@/services/evaluationApi'

// Mock the backend client so no real request is made and we can inspect the
// exact payload the store uploads for each evaluation mode.
const evaluateNotes = vi.fn<
  (
    notebooks: Notebook[],
    pages: Page[],
    notebookId?: string,
    pageId?: string
  ) => Promise<EvaluationResult>
>()

vi.mock('@/services/evaluationApi', () => ({
  evaluateNotes: (...args: Parameters<typeof evaluateNotes>) => evaluateNotes(...args)
}))

import { useProgressStore } from '@/stores/progressStore'
import { useNotesStore } from '@/stores/notesStore'

describe('progressStore.evaluate — request scoping', () => {
  beforeEach(() => {
    localStorage.clear()
    setActivePinia(createPinia())
    evaluateNotes.mockReset()
    evaluateNotes.mockResolvedValue({ pageScores: {}, notebookScores: {} })
  })

  it('single-page mode uploads only the target page and forwards its pageId', async () => {
    const notes = useNotesStore()
    const nb = notes.addNotebook('Study')
    const parent = notes.addPage(nb.id, null, 'Parent')
    const child = notes.addPage(nb.id, parent.id, 'Child')
    notes.addPage(nb.id, parent.id, 'Sibling')

    const progress = useProgressStore()
    await progress.evaluate({ notebookId: nb.id, pageId: child.id })

    expect(evaluateNotes).toHaveBeenCalledTimes(1)
    const [notebooks, pages, notebookId, pageId] = evaluateNotes.mock.calls[0]!

    // Only the requested page is sent — not the parent or the sibling subpage.
    expect(pages.map((p) => p.id)).toEqual([child.id])
    expect(notebookId).toBe(nb.id)
    expect(pageId).toBe(child.id)
    // Only the owning notebook is sent.
    expect(notebooks.map((n) => n.id)).toEqual([nb.id])
  })

  it('single-page mode infers the owning notebook when notebookId is omitted', async () => {
    const notes = useNotesStore()
    const nb = notes.addNotebook('Study')
    const page = notes.addPage(nb.id, null, 'Solo')

    const progress = useProgressStore()
    await progress.evaluate({ pageId: page.id })

    const [notebooks, pages, , pageId] = evaluateNotes.mock.calls[0]!
    expect(pages.map((p) => p.id)).toEqual([page.id])
    expect(pageId).toBe(page.id)
    expect(notebooks.map((n) => n.id)).toEqual([nb.id])
  })

  it('notebook mode uploads every page of that notebook and no pageId', async () => {
    const notes = useNotesStore()
    const target = notes.addNotebook('Target')
    const other = notes.addNotebook('Other')
    const p1 = notes.addPage(target.id, null, 'One')
    const p2 = notes.addPage(target.id, p1.id, 'Two')
    notes.addPage(other.id, null, 'Elsewhere')

    const progress = useProgressStore()
    await progress.evaluate({ notebookId: target.id })

    const [notebooks, pages, notebookId, pageId] = evaluateNotes.mock.calls[0]!
    expect(new Set(pages.map((p) => p.id))).toEqual(new Set([p1.id, p2.id]))
    expect(pages.every((p) => p.notebookId === target.id)).toBe(true)
    expect(notebooks.map((n) => n.id)).toEqual([target.id])
    expect(notebookId).toBe(target.id)
    expect(pageId).toBeUndefined()
  })

  it('evaluate-all mode uploads the entire dataset with no filters', async () => {
    const notes = useNotesStore()
    const progress = useProgressStore()
    await progress.evaluate()

    const [notebooks, pages, notebookId, pageId] = evaluateNotes.mock.calls[0]!
    expect(pages).toHaveLength(notes.pages.length)
    expect(notebooks).toHaveLength(notes.notebooks.length)
    expect(notebookId).toBeUndefined()
    expect(pageId).toBeUndefined()
  })

  it('records lastEvaluatedAt on success and surfaces errors on failure', async () => {
    const notes = useNotesStore()
    const nb = notes.addNotebook('Study')
    const page = notes.addPage(nb.id, null, 'Solo')
    const progress = useProgressStore()

    await progress.evaluate({ pageId: page.id })
    expect(progress.error).toBeNull()
    expect(progress.lastEvaluatedAt).not.toBeNull()
    expect(progress.loading).toBe(false)

    evaluateNotes.mockRejectedValueOnce(new Error('boom'))
    await progress.evaluate({ pageId: page.id })
    expect(progress.error).toBe('boom')
    expect(progress.loading).toBe(false)
  })
})

import { defineStore } from 'pinia'
import { evaluateNotes } from '@/services/evaluationApi'
import { clearProgress, setLiveScores } from '@/utils/progress'
import { useNotesStore } from './notesStore'

interface State {
  /** True while an evaluation request is in flight. */
  loading: boolean
  /** Last error message, if the most recent evaluation failed. */
  error: string | null
  /** ISO timestamp of the last successful evaluation. */
  lastEvaluatedAt: string | null
}

/**
 * Optional convenience wrapper around backend evaluation. `AppLayout.vue`
 * currently drives evaluation inline, but this store offers the same behaviour
 * for components that prefer a shared, reactive loading/error state.
 */
export const useProgressStore = defineStore('progress', {
  state: (): State => ({
    loading: false,
    error: null,
    lastEvaluatedAt: null
  }),

  actions: {
    /**
     * Send notebooks + pages to the backend and merge the returned page and
     * notebook scores into the progress cache.
     *
     * @param notebookId Optional — evaluate only this notebook.
     */
    async evaluate(notebookId?: string) {
      const notes = useNotesStore()
      this.loading = true
      this.error = null
      try {
        // A single-notebook evaluation must not upload unrelated notebooks or
        // pages. Evaluate All intentionally keeps the complete dataset.
        const notebooks = notebookId
          ? notes.notebooks.filter((notebook) => notebook.id === notebookId)
          : notes.notebooks
        const pages = notebookId
          ? notes.pages.filter((page) => page.notebookId === notebookId)
          : notes.pages

        const { pageScores, notebookScores } = await evaluateNotes(
          notebooks,
          pages,
          notebookId
        )
        setLiveScores(pageScores)
        setLiveScores(notebookScores)
        this.lastEvaluatedAt = new Date().toISOString()
      } catch (e) {
        this.error = e instanceof Error ? e.message : String(e)
      } finally {
        this.loading = false
      }
    },

    /** Drop all cached scores (e.g. after resetting to seed data). */
    reset() {
      clearProgress()
      this.lastEvaluatedAt = null
      this.error = null
    }
  }
})

import { defineStore } from 'pinia'
import { evaluateNotes } from '@/services/evaluationApi'
import { clearProgress, setLiveScores } from '@/utils/progress'
import { useNotesStore } from './notesStore'

interface State {
  /** True while an evaluation request is in flight. */
  loading: boolean
  /** Last error message, if the most recent evaluation failed. */
  error: string | null
  /** ISO timestamp of the last successful evaluation. */
  lastEvaluatedAt: string | null
}

/**
 * Optional convenience wrapper around backend evaluation. `AppLayout.vue`
 * currently drives evaluation inline, but this store offers the same behaviour
 * for components that prefer a shared, reactive loading/error state.
 */
export const useProgressStore = defineStore('progress', {
  state: (): State => ({
    loading: false,
    error: null,
    lastEvaluatedAt: null
  }),

  actions: {
    /**
     * Send notebooks + pages to the backend and merge the returned page and
     * notebook scores into the progress cache.
     *
     * @param options.notebookId Optional — evaluate only this notebook.
     * @param options.pageId     Optional — evaluate only this single page. Takes
     *   precedence over `notebookId`; no other page (parent or sibling subpage)
     *   is scored, keeping the request cheap for large page trees.
     */
    async evaluate(options: { notebookId?: string; pageId?: string } = {}) {
      const { notebookId, pageId } = options
      const notes = useNotesStore()
      this.loading = true
      this.error = null
      try {
        // Only upload what is being evaluated. A single-page request sends just
        // that page; a notebook request sends that notebook's pages; "Evaluate
        // All" keeps the complete dataset.
        let notebooks = notes.notebooks
        let pages = notes.pages
        if (pageId) {
          const page = notes.pages.find((p) => p.id === pageId)
          pages = page ? [page] : []
          const owningId = notebookId ?? page?.notebookId
          notebooks = owningId
            ? notes.notebooks.filter((notebook) => notebook.id === owningId)
            : notes.notebooks
        } else if (notebookId) {
          notebooks = notes.notebooks.filter((notebook) => notebook.id === notebookId)
          pages = notes.pages.filter((page) => page.notebookId === notebookId)
        }

        const { pageScores, notebookScores } = await evaluateNotes(
          notebooks,
          pages,
          notebookId,
          pageId
        )
        setLiveScores(pageScores)
        setLiveScores(notebookScores)
        this.lastEvaluatedAt = new Date().toISOString()
      } catch (e) {
        this.error = e instanceof Error ? e.message : String(e)
      } finally {
        this.loading = false
      }
    },

    /** Drop all cached scores (e.g. after resetting to seed data). */
    reset() {
      clearProgress()
      this.lastEvaluatedAt = null
      this.error = null
    }
  }
})

/**
 * Core domain types for the OneNote-style notes app.
 *
 * Hierarchy:
 *   Notebook (1) ──< Page (many, tree via parentId)
 *
 *   Notebook { id, title, color, pages[] }
 *   Page     { id, notebookId, parentId|null, title, content, order }
 *
 * A Page self-references through `parentId` allowing unlimited nesting.
 * `children` is not stored on the raw Page — it is derived at runtime by the
 * store's tree-building helpers (see PageNode).
 */

export interface Notebook {
  id: string
  title: string
  /** Accent color used for the notebook chip / active state. */
  color: string
}

/**
 * An inline reference (link) inside a text box. It points a character range of
 * the box `text` at another page. Offsets are half-open `[start, end)` indices
 * into the box text at the moment the link was created. They are best-effort:
 * edits that alter the linked substring drop the reference (see the store's
 * prune-on-edit logic).
 */
export interface TextReference {
  id: string
  /** Inclusive start offset into the owning box's `text`. */
  start: number
  /** Exclusive end offset into the owning box's `text`. */
  end: number
  /** Id of the page this range links to. */
  targetPageId: string
}

/**
 * A free-floating text box placed on the page canvas (OneNote style).
 * Position is stored in pixels relative to the top-left of the canvas.
 * Empty boxes are never persisted — they live only as local drafts until
 * the user types something into them.
 */
export interface TextBox {
  id: string
  /** Horizontal offset in px from the canvas left edge. */
  x: number
  /** Vertical offset in px from the canvas top edge. */
  y: number
  text: string
  /** Optional authored width in px (auto if omitted). */
  width?: number
  /** Inline page references (links) placed within `text`. */
  references?: TextReference[]
}

export interface Page {
  id: string
  notebookId: string
  /** null => top-level page directly under the notebook. */
  parentId: string | null
  title: string
  /** Editor body (plain text / HTML depending on editor implementation). */
  content: string
  /** Free-positioned text boxes placed on the page canvas. */
  boxes: TextBox[]
  /** Sort order among siblings. */
  order: number
}

/**
 * A Page enriched with its resolved children — the recursive shape consumed by
 * the PageTree / PageTreeItem components.
 */
export interface PageNode extends Page {
  children: PageNode[]
}

/**
 * A notebook paired with its resolved page tree — consumed by the reference
 * picker to render a collapsible notebook → page selector.
 */
export interface NotebookTree {
  notebook: Notebook
  tree: PageNode[]
}

/** Request to create or update a notebook. */
export interface NotebookRequest {
  title: string
  color: string
}

/** Request to create or update a page. */
export interface PageRequest {
  parentId?: string | null
  title: string
  content: string
  order?: number
  boxes?: TextBoxPayload[]
}

/** Payload for a TextBox in page save requests/responses. */
export interface TextBoxPayload {
  id?: string
  x: number
  y: number
  width?: number
  text: string
  references?: TextReferencePayload[]
}

/** Payload for a TextReference in page save requests/responses. */
export interface TextReferencePayload {
  id?: string
  start: number
  end: number
  targetPageId: string
}

/** Response from POST /api/voice/chat — a spoken tutor reply to a recorded explanation. */
export interface VoiceChatResponse {
  /** What the learner said, transcribed separately from their recorded audio. */
  userTranscript: string
  transcript: string
  /** Base64-encoded WAV audio. */
  audioData: string
}

/**
 * Core domain types for the OneNote-style notes app.
 *
 * Hierarchy:
 *   Notebook (1) ──< Page (many, tree via parentId)
 *
 *   Notebook { id, title, color, pages[] }
 *   Page     { id, notebookId, parentId|null, title, content, order }
 *
 * A Page self-references through `parentId` allowing unlimited nesting.
 * `children` is not stored on the raw Page — it is derived at runtime by the
 * store's tree-building helpers (see PageNode).
 */

export interface Notebook {
  id: string
  title: string
  /** Accent color used for the notebook chip / active state. */
  color: string
}

/**
 * An inline reference (link) inside a text box. It points a character range of
 * the box `text` at another page. Offsets are half-open `[start, end)` indices
 * into the box text at the moment the link was created. They are best-effort:
 * edits that alter the linked substring drop the reference (see the store's
 * prune-on-edit logic).
 */
export interface TextReference {
  id: string
  /** Inclusive start offset into the owning box's `text`. */
  start: number
  /** Exclusive end offset into the owning box's `text`. */
  end: number
  /** Id of the page this range links to. */
  targetPageId: string
}

/**
 * A free-floating text box placed on the page canvas (OneNote style).
 * Position is stored in pixels relative to the top-left of the canvas.
 * Empty boxes are never persisted — they live only as local drafts until
 * the user types something into them.
 */
export interface TextBox {
  id: string
  /** Horizontal offset in px from the canvas left edge. */
  x: number
  /** Vertical offset in px from the canvas top edge. */
  y: number
  text: string
  /** Optional authored width in px (auto if omitted). */
  width?: number
  /** Inline page references (links) placed within `text`. */
  references?: TextReference[]
}

export interface Page {
  id: string
  notebookId: string
  /** null => top-level page directly under the notebook. */
  parentId: string | null
  title: string
  /** Editor body (plain text / HTML depending on editor implementation). */
  content: string
  /** Free-positioned text boxes placed on the page canvas. */
  boxes: TextBox[]
  /** Sort order among siblings. */
  order: number
}

/**
 * A Page enriched with its resolved children — the recursive shape consumed by
 * the PageTree / PageTreeItem components.
 */
export interface PageNode extends Page {
  children: PageNode[]
}

/**
 * A notebook paired with its resolved page tree — consumed by the reference
 * picker to render a collapsible notebook → page selector.
 */
export interface NotebookTree {
  notebook: Notebook
  tree: PageNode[]
}

/** Request to create or update a notebook. */
export interface NotebookRequest {
  title: string
  color: string
}

/** Request to create or update a page. */
export interface PageRequest {
  parentId?: string | null
  title: string
  content: string
  order?: number
  boxes?: TextBoxPayload[]
}

/** Payload for a TextBox in page save requests/responses. */
export interface TextBoxPayload {
  id?: string
  x: number
  y: number
  width?: number
  text: string
  references?: TextReferencePayload[]
}

/** Payload for a TextReference in page save requests/responses. */
export interface TextReferencePayload {
  id?: string
  start: number
  end: number
  targetPageId: string
}

/** Response from POST /api/voice/chat — a spoken tutor reply to a recorded explanation. */
export interface VoiceChatResponse {
  /** What the learner said, transcribed separately from their recorded audio. */
  userTranscript: string
  transcript: string
  /** Base64-encoded WAV audio. */
  audioData: string
}

/** One completed exchange in a voice tutoring session. */
export interface VoiceTurn {
  id: string
  /** What the learner said. */
  userTranscript: string
  /** The tutor's spoken reply, as text. */
  tutorTranscript: string
  /** Base64-encoded WAV of the tutor reply, so past replies stay replayable. */
  audioData: string
}

/** A prior turn, flattened for sending back to the model as conversation context. */
export interface VoiceHistoryMessage {
  role: 'user' | 'assistant'
  text: string
}

import { describe, it, expect } from 'vitest'
import {
  DEFAULT_THRESHOLDS,
  progressLevel,
  getProgress
} from '@/utils/progress'

describe('progressLevel', () => {
  it('returns "danger" below the danger threshold (< 33)', () => {
    expect(progressLevel(0)).toBe('danger')
    expect(progressLevel(32)).toBe('danger')
  })

  it('returns "warn" between danger and warn thresholds (33–74)', () => {
    expect(progressLevel(33)).toBe('warn')
    expect(progressLevel(74)).toBe('warn')
  })

  it('returns "good" at/above the warn threshold (>= 75)', () => {
    expect(progressLevel(75)).toBe('good')
    expect(progressLevel(100)).toBe('good')
  })

  it('honours custom thresholds', () => {
    expect(progressLevel(50, { danger: 60, warn: 90 })).toBe('danger')
    expect(progressLevel(80, { danger: 60, warn: 90 })).toBe('warn')
    expect(progressLevel(95, { danger: 60, warn: 90 })).toBe('good')
  })

  it('exposes sensible defaults', () => {
    expect(DEFAULT_THRESHOLDS).toEqual({ danger: 33, warn: 75 })
  })
})

describe('getProgress', () => {
  it('is deterministic for the same id', () => {
    expect(getProgress('nb-1')).toBe(getProgress('nb-1'))
  })

  it('always returns a value within 0–100', () => {
    for (const id of ['a', 'nb-1', 'pg-xyz', 'longer-id-string']) {
      const v = getProgress(id)
      expect(v).toBeGreaterThanOrEqual(0)
      expect(v).toBeLessThanOrEqual(100)
    }
  })
})

import { describe, it, expect, beforeEach } from 'vitest'
import {
  DEFAULT_THRESHOLDS,
  progressLevel,
  getProgress,
  setProgress,
  setLiveScores,
  clearProgress,
  DEFAULT_PROGRESS
} from '@/utils/progress'

describe('progressLevel', () => {
  it('returns "danger" below the danger threshold (< 33)', () => {
    expect(progressLevel(0)).toBe('danger')
    expect(progressLevel(32)).toBe('danger')
  })

  it('returns "warn" between danger and warn thresholds (33–74)', () => {
    expect(progressLevel(33)).toBe('warn')
    expect(progressLevel(74)).toBe('warn')
  })

  it('returns "good" at/above the warn threshold (>= 75)', () => {
    expect(progressLevel(75)).toBe('good')
    expect(progressLevel(100)).toBe('good')
  })

  it('honours custom thresholds', () => {
    expect(progressLevel(50, { danger: 60, warn: 90 })).toBe('danger')
    expect(progressLevel(80, { danger: 60, warn: 90 })).toBe('warn')
    expect(progressLevel(95, { danger: 60, warn: 90 })).toBe('good')
  })

  it('exposes sensible defaults', () => {
    expect(DEFAULT_THRESHOLDS).toEqual({ danger: 33, warn: 75 })
  })
})

describe('getProgress', () => {
  beforeEach(() => {
    clearProgress()
  })

  it('returns the default for unknown ids', () => {
    expect(getProgress('nb-unknown')).toBe(DEFAULT_PROGRESS)
  })

  it('is deterministic for the same id', () => {
    expect(getProgress('nb-1')).toBe(getProgress('nb-1'))
  })

  it('always returns a value within 0–100', () => {
    for (const id of ['a', 'nb-1', 'pg-xyz', 'longer-id-string']) {
      const v = getProgress(id)
      expect(v).toBeGreaterThanOrEqual(0)
      expect(v).toBeLessThanOrEqual(100)
    }
  })

  it('reflects a value stored via setProgress (clamped + rounded)', () => {
    setProgress('nb-1', 73.6)
    expect(getProgress('nb-1')).toBe(74)
    setProgress('nb-1', 250)
    expect(getProgress('nb-1')).toBe(100)
    setProgress('nb-1', -10)
    expect(getProgress('nb-1')).toBe(0)
  })

  it('merges backend results via setLiveScores', () => {
    setLiveScores({
      'nb-work': { score: 62, understandingNotes: 'ok' },
      'pg-feynman': { score: 88, understandingNotes: 'clear explanation' }
    })
    expect(getProgress('nb-work')).toBe(62)
    expect(getProgress('pg-feynman')).toBe(88)
  })

  it('clearProgress resets the cache', () => {
    setProgress('nb-1', 50)
    clearProgress()
    expect(getProgress('nb-1')).toBe(DEFAULT_PROGRESS)
  })
})

/**
 * Progress model for notebooks and pages.
 *
 * ─────────────────────────────────────────────────────────────────────────
 * BACKEND SEAM
 * ─────────────────────────────────────────────────────────────────────────
 * Progress values are now provided by the Spring Boot backend, which asks an
 * LLM (or a deterministic offline heuristic) to grade how well each notebook /
 * page topic appears to be understood — following the Feynman technique.
 *
 * The backend result is cached in-module via `setProgress` / `setProgresses`
 * (populated by `useProgressStore`), so the widely-used `getProgress(id)`
 * accessor stays synchronous for templates.
 *
 * Color thresholds are centralized here so they can be made user-customizable
 * later without touching the components.
 */

export interface ProgressThresholds {
  /** Below this percent → "danger" (red). */
  danger: number
  /** Below this percent → "warn" (yellow); at/above → "good" (green). */
  warn: number
}

/** Default thresholds: red < 33, yellow < 75, green ≥ 75. */
export const DEFAULT_THRESHOLDS: ProgressThresholds = {
  danger: 33,
  warn: 75
}

export type ProgressLevel = 'danger' | 'warn' | 'good'

/**
 * Map a percent value to a color level using the given thresholds.
 */
export function progressLevel(
  value: number,
  thresholds: ProgressThresholds = DEFAULT_THRESHOLDS
): ProgressLevel {
  if (value < thresholds.danger) return 'danger'
  if (value < thresholds.warn) return 'warn'
  return 'good'
}

/**
 * In-memory cache of backend-evaluated scores, keyed by notebook / page id.
 * Populated by `useProgressStore.evaluate()` after calling the backend.
 */
const scoreCache: Record<string, number> = {}

/**
 * In-memory cache of the LLM's short "understanding notes" per id, shown as a
 * tooltip on the progress badge so users can see WHY a topic scored as it did.
 */
const notesCache: Record<string, string> = {}

/**
 * Fallback percent for ids the backend has not evaluated yet (e.g. a newly
 * created notebook/page, or before the first evaluation completes).
 */
export const DEFAULT_PROGRESS = 0

/** Clamp a raw value into the valid 0–100 progress range. */
function clamp(value: number): number {
  if (Number.isNaN(value)) return DEFAULT_PROGRESS
  return Math.max(0, Math.min(100, Math.round(value)))
}

/** Store a single backend-evaluated score. */
export function setProgress(id: string, value: number): void {
  scoreCache[id] = clamp(value)
}

/** Bulk-store backend-evaluated scores (id → percent). */
export function setProgresses(scores: Record<string, number>): void {
  for (const [id, value] of Object.entries(scores)) {
    scoreCache[id] = clamp(value)
  }
}

/**
 * Merge backend evaluation results into the progress cache.
 *
 * Accepts the `{ score, understandingNotes }` shape returned by the backend
 * (see `evaluationApi.ts`), so callers can pass `pageScores` / `notebookScores`
 * directly.
 */
export function setLiveScores(
  scores: Record<string, { score: number; understandingNotes?: string }>
): void {
  for (const [id, entry] of Object.entries(scores)) {
    if (entry && typeof entry.score === 'number') {
      scoreCache[id] = clamp(entry.score)
      if (entry.understandingNotes) {
        notesCache[id] = entry.understandingNotes
      }
    }
  }
}

/** Clear all cached scores (e.g. on reset-to-seed). */
export function clearProgress(): void {
  for (const key of Object.keys(scoreCache)) delete scoreCache[key]
  for (const key of Object.keys(notesCache)) delete notesCache[key]
}

/**
 * Return the progress percent (0–100) for a notebook or page id.
 *
 * Reads from the backend-populated cache; returns `DEFAULT_PROGRESS` for ids
 * that have not been evaluated yet.
 */
export function getProgress(id: string): number {
  return scoreCache[id] ?? DEFAULT_PROGRESS
}

/**
 * Return the LLM's understanding notes for an id, or an empty string if the id
 * has not been evaluated (or the backend returned no notes).
 */
export function getUnderstandingNotes(id: string): string {
  return notesCache[id] ?? ''
}

/**
 * Progress model for notebooks and pages.
 *
 * ─────────────────────────────────────────────────────────────────────────
 * BACKEND SEAM
 * ─────────────────────────────────────────────────────────────────────────
 * Progress values are now provided by the Spring Boot backend, which asks an
 * LLM (or a deterministic offline heuristic) to grade how well each notebook /
 * page topic appears to be understood — following the Feynman technique.
 *
 * The backend result is cached in-module via `setProgress` / `setProgresses`
 * (populated by `useProgressStore`), so the widely-used `getProgress(id)`
 * accessor stays synchronous for templates.
 *
 * Color thresholds are centralized here so they can be made user-customizable
 * later without touching the components.
 */

import { ref } from 'vue'

export interface ProgressThresholds {
  /** Below this percent → "danger" (red). */
  danger: number
  /** Below this percent → "warn" (yellow); at/above → "good" (green). */
  warn: number
}

/** Default thresholds: red < 33, yellow < 75, green ≥ 75. */
export const DEFAULT_THRESHOLDS: ProgressThresholds = {
  danger: 33,
  warn: 75
}

export type ProgressLevel = 'danger' | 'warn' | 'good'

/**
 * Reactive counter bumped whenever cached scores/feedback change. Components can
 * read it inside a `computed` to establish a reactive dependency on the
 * otherwise plain (non-reactive) caches, so they refresh after an evaluation.
 */
export const scoreVersion = ref(0)

/**
 * Map a percent value to a color level using the given thresholds.
 */
export function progressLevel(
  value: number,
  thresholds: ProgressThresholds = DEFAULT_THRESHOLDS
): ProgressLevel {
  if (value < thresholds.danger) return 'danger'
  if (value < thresholds.warn) return 'warn'
  return 'good'
}

/**
 * In-memory cache of backend-evaluated scores, keyed by notebook / page id.
 * Populated by `useProgressStore.evaluate()` after calling the backend.
 */
const scoreCache: Record<string, number> = {}

/**
 * In-memory cache of the LLM's short "understanding notes" per id, shown as a
 * tooltip on the progress badge so users can see WHY a topic scored as it did.
 */
const notesCache: Record<string, string> = {}

/**
 * In-memory cache of the LLM's longer, actionable "feedback" per id, shown as a
 * distinguishable callout inside the evaluated notebook.
 */
const feedbackCache: Record<string, string> = {}

/**
 * Fallback percent for ids the backend has not evaluated yet (e.g. a newly
 * created notebook/page, or before the first evaluation completes).
 */
export const DEFAULT_PROGRESS = 0

/** Clamp a raw value into the valid 0–100 progress range. */
function clamp(value: number): number {
  if (Number.isNaN(value)) return DEFAULT_PROGRESS
  return Math.max(0, Math.min(100, Math.round(value)))
}

/** Store a single backend-evaluated score. */
export function setProgress(id: string, value: number): void {
  scoreCache[id] = clamp(value)
}

/** Bulk-store backend-evaluated scores (id → percent). */
export function setProgresses(scores: Record<string, number>): void {
  for (const [id, value] of Object.entries(scores)) {
    scoreCache[id] = clamp(value)
  }
}

/**
 * Merge backend evaluation results into the progress cache.
 *
 * Accepts the `{ score, understandingNotes }` shape returned by the backend
 * (see `evaluationApi.ts`), so callers can pass `pageScores` / `notebookScores`
 * directly.
 */
export function setLiveScores(
  scores: Record<string, { score: number; understandingNotes?: string; feedback?: string }>
): void {
  for (const [id, entry] of Object.entries(scores)) {
    if (entry && typeof entry.score === 'number') {
      scoreCache[id] = clamp(entry.score)
      if (entry.understandingNotes) {
        notesCache[id] = entry.understandingNotes
      }
      if (entry.feedback) {
        feedbackCache[id] = entry.feedback
      }
    }
  }
  scoreVersion.value++
}

/** Clear all cached scores (e.g. on reset-to-seed). */
export function clearProgress(): void {
  for (const key of Object.keys(scoreCache)) delete scoreCache[key]
  for (const key of Object.keys(notesCache)) delete notesCache[key]
  for (const key of Object.keys(feedbackCache)) delete feedbackCache[key]
  scoreVersion.value++
}

/**
 * Return the progress percent (0–100) for a notebook or page id.
 *
 * Reads from the backend-populated cache; returns `DEFAULT_PROGRESS` for ids
 * that have not been evaluated yet.
 */
export function getProgress(id: string): number {
  return scoreCache[id] ?? DEFAULT_PROGRESS
}

/**
 * Return the LLM's understanding notes for an id, or an empty string if the id
 * has not been evaluated (or the backend returned no notes).
 */
export function getUnderstandingNotes(id: string): string {
  return notesCache[id] ?? ''
}

/**
 * Return the LLM's longer feedback paragraph for an id, or an empty string if
 * the id has not been evaluated (or the backend returned no feedback).
 */
export function getFeedback(id: string): string {
  return feedbackCache[id] ?? ''
}
